import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { 
  Play, 
  Pause, 
  Upload, 
  Scissors, 
  Trash2, 
  RotateCcw, 
  Volume2, 
  Maximize,
  FileAudio,
  Download
} from 'lucide-react';

// --- Types ---
interface AudioState {
  file: File | null;
  url: string | null;
  duration: number;
  currentTime: number;
  isPlaying: boolean;
  isReady: boolean;
}

// --- App Component ---
const App: React.FC = () => {
  const [audio, setAudio] = useState<AudioState>({
    file: null,
    url: null,
    duration: 0,
    currentTime: 0,
    isPlaying: false,
    isReady: false,
  });

  const [zoom, setZoom] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [activeRegion, setActiveRegion] = useState<any>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const wavesurferRef = useRef<WaveSurfer | null>(null);
  const regionsRef = useRef<any>(null);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !audio.url) return;

    // Destroy existing instance if any
    if (wavesurferRef.current) {
      wavesurferRef.current.destroy();
    }

    const ws = WaveSurfer.create({
      container: containerRef.current,
      waveColor: '#6366f1',
      progressColor: '#a5b4fc',
      cursorColor: '#f8fafc',
      barWidth: 2,
      barGap: 1,
      height: 256,
      normalize: true,
      splitChannels: true, // Show 2 channels for stereo
      url: audio.url,
      minPxPerSec: 50,
    });

    const regions = ws.registerPlugin(RegionsPlugin.create());
    regionsRef.current = regions;

    ws.on('ready', () => {
      setAudio(prev => ({ ...prev, duration: ws.getDuration(), isReady: true }));
    });

    ws.on('play', () => setAudio(prev => ({ ...prev, isPlaying: true })));
    ws.on('pause', () => setAudio(prev => ({ ...prev, isPlaying: false })));
    ws.on('timeupdate', (time) => setAudio(prev => ({ ...prev, currentTime: time })));

    // Enable region creation on drag
    regions.enableDragSelection({
      color: 'rgba(99, 102, 241, 0.2)',
    });

    regions.on('region-created', (region) => {
      // Clear other regions to keep it simple (only one boundary)
      regions.getRegions().forEach(r => {
        if (r !== region) r.remove();
      });
      setActiveRegion(region);
    });

    regions.on('region-updated', (region) => {
      setActiveRegion(region);
    });

    wavesurferRef.current = ws;

    return () => {
      ws.destroy();
    };
  }, [audio.url]);

  const handleFileUpload = (file: File) => {
    if (file && file.type.startsWith('audio/')) {
      const url = URL.createObjectURL(file);
      setAudio({
        file,
        url,
        duration: 0,
        currentTime: 0,
        isPlaying: false,
        isReady: false,
      });
      setActiveRegion(null);
    }
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    handleFileUpload(file);
  }, []);

  const onDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(true);
  }, []);

  const onDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
  }, []);

  const togglePlay = () => {
    if (wavesurferRef.current) {
      wavesurferRef.current.playPause();
    }
  };

  const playRegion = () => {
    if (activeRegion) {
      activeRegion.play();
    }
  };

  const clearRegion = () => {
    if (regionsRef.current) {
      regionsRef.current.clearRegions();
      setActiveRegion(null);
    }
  };

  const handleZoom = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(e.target.value);
    setZoom(value);
    if (wavesurferRef.current) {
      wavesurferRef.current.zoom(value);
    }
  };

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div 
      className={`min-h-screen flex flex-col p-6 transition-colors duration-300 ${isDragging ? 'bg-indigo-950/20' : 'bg-slate-900'}`}
      onDrop={onDrop}
      onDragOver={onDragOver}
      onDragLeave={onDragLeave}
    >
      {/* Header */}
      <header className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg">
            <Volume2 className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-white">AudioWave <span className="text-indigo-400">Editor</span></h1>
        </div>

        <label className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-slate-200 px-4 py-2 rounded-full cursor-pointer transition-all border border-slate-700">
          <Upload className="w-4 h-4" />
          <span className="text-sm font-medium">Upload File</span>
          <input 
            type="file" 
            className="hidden" 
            accept="audio/*" 
            onChange={(e) => e.target.files && handleFileUpload(e.target.files[0])}
          />
        </label>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col items-center justify-center">
        {!audio.url ? (
          <div className="text-center p-12 border-2 border-dashed border-slate-700 rounded-3xl max-w-lg w-full bg-slate-800/50">
            <FileAudio className="w-16 h-16 text-slate-600 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-slate-300 mb-2">No audio loaded</h2>
            <p className="text-slate-500 mb-6">Drag and drop your audio file here or use the upload button above.</p>
            <div className="text-xs text-slate-600 uppercase tracking-widest font-bold">Supports MP3, WAV, OGG, M4A</div>
          </div>
        ) : (
          <div className="w-full max-w-6xl space-y-6">
            {/* Waveform Card */}
            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-2xl overflow-hidden">
              <div className="flex justify-between items-center mb-4">
                <div>
                  <h3 className="text-indigo-400 font-medium text-sm mb-1">CURRENT FILE</h3>
                  <p className="text-white font-semibold truncate max-w-md">{audio.file?.name}</p>
                </div>
                <div className="text-right">
                  <p className="text-slate-400 text-sm">{formatTime(audio.currentTime)} / {formatTime(audio.duration)}</p>
                </div>
              </div>

              <div 
                ref={containerRef} 
                className="waveform-container rounded-lg bg-slate-900/50 p-2 border border-slate-700/50"
              />

              <div className="mt-4 flex items-center justify-between text-xs text-slate-500 font-mono">
                <span>CHANNEL L</span>
                <span className="h-px flex-1 mx-4 bg-slate-700/50"></span>
                <span>CHANNEL R</span>
              </div>
            </div>

            {/* Controls Bar */}
            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-4 flex flex-wrap items-center justify-between gap-6 shadow-xl">
              <div className="flex items-center gap-2">
                <button 
                  onClick={togglePlay}
                  disabled={!audio.isReady}
                  className="w-12 h-12 flex items-center justify-center rounded-full bg-indigo-600 hover:bg-indigo-500 text-white transition-all disabled:opacity-50"
                >
                  {audio.isPlaying ? <Pause /> : <Play className="ml-1" />}
                </button>
                <button 
                  onClick={() => wavesurferRef.current?.stop()}
                  className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-700 hover:bg-slate-600 text-slate-200 transition-all"
                >
                  <RotateCcw className="w-5 h-5" />
                </button>
              </div>

              <div className="flex items-center gap-4 flex-1 max-w-xs">
                <Maximize className="w-4 h-4 text-slate-500" />
                <input 
                  type="range" 
                  min="0" 
                  max="500" 
                  value={zoom} 
                  onChange={handleZoom}
                  className="flex-1 accent-indigo-500 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer"
                />
              </div>

              <div className="flex items-center gap-3 border-l border-slate-700 pl-6">
                {activeRegion ? (
                  <>
                    <button 
                      onClick={playRegion}
                      className="flex items-center gap-2 px-4 py-2 bg-emerald-600/20 text-emerald-400 hover:bg-emerald-600/30 rounded-lg transition-all text-sm font-semibold border border-emerald-600/30"
                    >
                      <Play className="w-4 h-4" /> Play Selection
                    </button>
                    <button 
                      onClick={clearRegion}
                      className="p-2 text-slate-400 hover:text-rose-400 transition-colors"
                      title="Clear Selection"
                    >
                      <Trash2 className="w-5 h-5" />
                    </button>
                  </>
                ) : (
                  <div className="flex items-center gap-2 text-slate-500 text-sm bg-slate-900/50 px-4 py-2 rounded-lg border border-slate-700/50 italic">
                    <Scissors className="w-4 h-4" />
                    Drag on wave to select a boundary
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      {/* Footer Info */}
      <footer className="mt-8 text-center text-slate-600 text-xs">
        <p>Built with Gemini & WaveSurfer.js • Stereoscopic Dual-Channel Support</p>
      </footer>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

