    setAudio(prev => ({ ...prev, isProcessing: true }));
    try {
      const response = await fetch(originalUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      // Create mono buffer
      const offlineCtx = new OfflineAudioContext(1, audioBuffer.length, audioBuffer.sampleRate);
      const source = offlineCtx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(offlineCtx.destination);
      source.start();

      const monoBuffer = await offlineCtx.startRendering();
      const monoBlob = audioBufferToWav(monoBuffer);
      return URL.createObjectURL(monoBlob);
    } catch (error) {
      console.error("Mixing failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false }));
      return null;
    }
  };

  const toggleMono = async () => {
    if (!audio.originalUrl) return;

