      </header>

      <main className="flex-1 flex flex-col items-center justify-center">
        {!audio.currentUrl ? (
          <div className="text-center p-12 border-2 border-dashed border-slate-700 rounded-3xl max-w-lg w-full bg-slate-800/50">
            <FileAudio className="w-16 h-16 text-slate-600 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-slate-300 mb-2">No audio loaded</h2>
            <p className="text-slate-500 mb-6 text-sm">Drag and drop audio here to begin true multi-channel editing.</p>
          </div>
        ) : (
          <div className="w-full max-w-6xl space-y-6">
            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-2xl relative overflow-hidden">
              {audio.isProcessing && (
                <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center">
                  <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                  <p className="text-white font-medium">Mixing audio to Mono...</p>
                  <p className="text-slate-400 text-xs mt-1">Applying true sample summation</p>
                </div>
              )}

              <div className="flex justify-between items-center mb-6">
                <div>
                  <h3 className="text-indigo-400 font-medium text-xs mb-1 uppercase tracking-widest">Workspace</h3>
                  <p className="text-white font-semibold truncate max-w-md">{audio.file?.name}</p>
                </div>
                <div className="text-right">
                  <p className="text-slate-400 text-sm font-mono">{formatTime(audio.currentTime)} / {formatTime(audio.duration)}</p>
                </div>
              </div>

              <div className="relative">
                {/* Repositioned Channel Labels (Pinned to top of each view) */}
                {!audio.isMono && (
                  <>
                    <div className="absolute top-2 left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
