              <div className="flex items-center gap-4 flex-1 max-w-[200px]">
                <Maximize className="w-4 h-4 text-slate-500" />
                <input type="range" min="0" max="500" value={zoom} onChange={handleZoom} className="flex-1 accent-indigo-500 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
              </div>

              <div className="flex items-center gap-3 border-l border-slate-700 pl-6">
                {activeRegion ? (
                  <>
                    <button onClick={playRegion} className="flex items-center gap-2 px-4 py-2 bg-emerald-600/20 text-emerald-400 hover:bg-emerald-600/30 rounded-lg transition-all text-sm font-semibold border border-emerald-600/30">
                      <Play className="w-4 h-4" /> Selection
                    </button>
                    <button onClick={clearRegion} className="p-2 text-slate-400 hover:text-rose-400 transition-colors">
                      <Trash2 className="w-5 h-5" />
                    </button>
                  </>
                ) : (
                  <div className="flex items-center gap-2 text-slate-500 text-xs bg-slate-900/50 px-4 py-2 rounded-lg border border-slate-700/50 italic select-none">
                    <Scissors className="w-4 h-4" />
                    Select range for playback
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="mt-8 text-center text-slate-600 text-[10px] uppercase tracking-[0.2em]">
        Experimental Audio Node v1.2 • Actual Sample Summation Logic
      </footer>
    </div>
  );
};

