      </main>

      <footer className="mt-8 text-center text-slate-600 text-[10px] uppercase tracking-[0.2em] flex flex-col gap-2">
        <span>Experimental Audio Node v1.3 • Sample Summation & Splice Engine</span>
        <div className="flex justify-center gap-4 opacity-50">
          <span>{audio.isMono ? 'Mono' : 'Stereo'} Mode</span>
          <span>{formatTime(audio.duration)} Buffer</span>
        </div>
