import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { 
  Play, 
  Pause, 
  Upload, 
  Scissors, 
  Trash2, 
  RotateCcw, 
  Volume2, 
  Maximize,
  FileAudio,
  Merge,
  Columns,
  Loader2,
  Download,
  X
} from 'lucide-react';

// --- Audio Helpers ---

function writeString(view: DataView, offset: number, string: string) {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
}

function audioBufferToWav(buffer: AudioBuffer): Blob {
  const numChannels = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;
  const format = 1; // PCM
  const bitDepth = 16;
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numChannels * bytesPerSample;
  const bufferLength = buffer.length * blockAlign;
  const arrayBuffer = new ArrayBuffer(44 + bufferLength);
  const view = new DataView(arrayBuffer);

  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + bufferLength, true);
  writeString(view, 8, 'WAVE');
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, format, true);
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * blockAlign, true);
  view.setUint16(32, blockAlign, true);
  view.setUint16(34, bitDepth, true);
  writeString(view, 36, 'data');
  view.setUint32(40, bufferLength, true);

  let offset = 44;
  for (let i = 0; i < buffer.length; i++) {
    for (let channel = 0; channel < numChannels; channel++) {
      let sample = buffer.getChannelData(channel)[i];
      sample = Math.max(-1, Math.min(1, sample));
      sample = sample < 0 ? sample * 0x8000 : sample * 0x7FFF;
      view.setInt16(offset, sample, true);
      offset += 2;
    }
  }
  return new Blob([arrayBuffer], { type: 'audio/wav' });
}

// --- Types ---

interface AudioState {
  file: File | null;
  originalUrl: string | null;
  currentUrl: string | null;
  monoUrl: string | null;
  duration: number;
  currentTime: number;
  isPlaying: boolean;
  isReady: boolean;
  isMono: boolean;
  isProcessing: boolean;
  processingMsg: string;
}

// --- App Component ---

const App: React.FC = () => {
  const [audio, setAudio] = useState<AudioState>({
    file: null,
    originalUrl: null,
    currentUrl: null,
    monoUrl: null,
    duration: 0,
    currentTime: 0,
    isPlaying: false,
    isReady: false,
    isMono: false,
    isProcessing: false,
    processingMsg: '',
  });

  const [zoom, setZoom] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [activeRegion, setActiveRegion] = useState<any>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const wavesurferRef = useRef<WaveSurfer | null>(null);
  const regionsRef = useRef<any>(null);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !audio.currentUrl) return;

    const currentTime = wavesurferRef.current?.getCurrentTime() || 0;
    const wasPlaying = wavesurferRef.current?.isPlaying() || false;

    if (wavesurferRef.current) {
      wavesurferRef.current.destroy();
    }

    const ws = WaveSurfer.create({
      container: containerRef.current,
      waveColor: '#6366f1',
      progressColor: '#a5b4fc',
      cursorColor: '#f8fafc',
      barWidth: 2,
      barGap: 1,
      height: 256,
      normalize: true,
      splitChannels: !audio.isMono,
      url: audio.currentUrl,
      minPxPerSec: 50,
    });

    const regions = ws.registerPlugin(RegionsPlugin.create());
    regionsRef.current = regions;

    ws.on('ready', () => {
      setAudio(prev => ({ ...prev, duration: ws.getDuration(), isReady: true, isProcessing: false, processingMsg: '' }));
      ws.setTime(currentTime > ws.getDuration() ? 0 : currentTime);
      if (wasPlaying) ws.play();
    });

    ws.on('play', () => setAudio(prev => ({ ...prev, isPlaying: true })));
    ws.on('pause', () => setAudio(prev => ({ ...prev, isPlaying: false })));
    ws.on('timeupdate', (time) => setAudio(prev => ({ ...prev, currentTime: time })));

    regions.enableDragSelection({
      color: 'rgba(99, 102, 241, 0.2)',
    });

    regions.on('region-created', (region) => {
      regions.getRegions().forEach(r => {
        if (r !== region) r.remove();
      });
      setActiveRegion(region);
    });

    regions.on('region-updated', (region) => {
      setActiveRegion(region);
    });

    wavesurferRef.current = ws;

    return () => {
      ws.destroy();
    };
  }, [audio.currentUrl, audio.isMono]);

  const handleFileUpload = (file: File) => {
    if (file && file.type.startsWith('audio/')) {
      if (audio.originalUrl) URL.revokeObjectURL(audio.originalUrl);
      if (audio.monoUrl) URL.revokeObjectURL(audio.monoUrl);

      const url = URL.createObjectURL(file);
      setAudio({
        file,
        originalUrl: url,
        currentUrl: url,
        monoUrl: null,
        duration: 0,
        currentTime: 0,
        isPlaying: false,
        isReady: false,
        isMono: false,
        isProcessing: false,
        processingMsg: '',
      });
      setActiveRegion(null);
    }
  };

  const downmixToMono = async (originalUrl: string) => {
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Mixing audio to Mono...' }));
    try {
      const response = await fetch(originalUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      // Create mono buffer
      const offlineCtx = new OfflineAudioContext(1, audioBuffer.length, audioBuffer.sampleRate);
      const source = offlineCtx.createBufferSource();
      source.buffer = audioBuffer;
      source.connect(offlineCtx.destination);
      source.start();

      const monoBuffer = await offlineCtx.startRendering();
      const monoBlob = audioBufferToWav(monoBuffer);
      return URL.createObjectURL(monoBlob);
    } catch (error) {
      console.error("Mixing failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
      return null;
    }
  };

  const handleCut = async () => {
    if (!activeRegion || !audio.currentUrl) return;

    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Cutting selection...' }));

    try {
      const start = activeRegion.start;
      const end = activeRegion.end;

      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const sampleRate = sourceBuffer.sampleRate;
      const numChannels = sourceBuffer.numberOfChannels;

      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);
      const cutSamples = endOffset - startOffset;
      const newLength = sourceBuffer.length - cutSamples;

      if (newLength <= 0) {
        alert("The resulting audio would be empty. Cut aborted.");
        setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
        return;
      }

      const newBuffer = audioCtx.createBuffer(numChannels, newLength, sampleRate);

      for (let channel = 0; channel < numChannels; channel++) {
        const oldData = sourceBuffer.getChannelData(channel);
        const newData = newBuffer.getChannelData(channel);

        // Data before selection
        newData.set(oldData.subarray(0, startOffset));
        // Data after selection
        newData.set(oldData.subarray(endOffset), startOffset);
      }

      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        originalUrl: audio.isMono ? prev.originalUrl : newUrl, // If cutting in stereo, update base
        monoUrl: audio.isMono ? newUrl : null, // If cutting in mono, this is the new mono
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Cut failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const toggleMono = async () => {
    if (!audio.originalUrl) return;

    if (!audio.isMono) {
      // Switching to Mono
      let monoUrl = audio.monoUrl;
      if (!monoUrl) {
        monoUrl = await downmixToMono(audio.originalUrl);
      }
      if (monoUrl) {
        setAudio(prev => ({
          ...prev,
          isMono: true,
          currentUrl: monoUrl,
          monoUrl: monoUrl
        }));
      }
    } else {
      // Switching back to Stereo
      setAudio(prev => ({
        ...prev,
        isMono: false,
        currentUrl: prev.originalUrl
      }));
    }
  };

  const handleDownload = () => {
    if (!audio.currentUrl) return;
    const link = document.createElement('a');
    link.href = audio.currentUrl;
    const originalName = audio.file?.name || 'audio';
    const nameWithoutExt = originalName.substring(0, originalName.lastIndexOf('.')) || originalName;
    link.download = `${nameWithoutExt}-edited.wav`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    handleFileUpload(file);
  }, [audio]);

  const togglePlay = () => wavesurferRef.current?.playPause();
  const playRegion = () => activeRegion?.play();
  const clearRegion = () => {
    regionsRef.current?.clearRegions();
    setActiveRegion(null);
  };

  const handleZoom = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(e.target.value);
    setZoom(value);
    wavesurferRef.current?.zoom(value);
  };

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div 
      className={`min-h-screen flex flex-col p-6 transition-colors duration-300 ${isDragging ? 'bg-indigo-950/20' : 'bg-slate-900'}`}
      onDrop={onDrop}
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
    >
      <header className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg">
            <Volume2 className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-white">AudioWave <span className="text-indigo-400">Editor</span></h1>
        </div>

        <div className="flex items-center gap-3">
          {audio.currentUrl && (
            <button 
              onClick={handleDownload}
              className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded-full transition-all shadow-lg shadow-emerald-600/20 border border-emerald-500/50"
            >
              <Download className="w-4 h-4" />
              <span className="text-sm font-medium">Save As</span>
            </button>
          )}

          <label className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-slate-200 px-4 py-2 rounded-full cursor-pointer transition-all border border-slate-700">
            <Upload className="w-4 h-4" />
            <span className="text-sm font-medium">Upload File</span>
            <input type="file" className="hidden" accept="audio/*" onChange={(e) => e.target.files && handleFileUpload(e.target.files[0])} />
          </label>
        </div>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center">
        {!audio.currentUrl ? (
          <div className="text-center p-12 border-2 border-dashed border-slate-700 rounded-3xl max-w-lg w-full bg-slate-800/50">
            <FileAudio className="w-16 h-16 text-slate-600 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-slate-300 mb-2">No audio loaded</h2>
            <p className="text-slate-500 mb-6 text-sm">Drag and drop audio here to begin multi-channel editing and cutting.</p>
          </div>
        ) : (
          <div className="w-full max-w-6xl space-y-6">
            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-2xl relative overflow-hidden">
              {audio.isProcessing && (
                <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center">
                  <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                  <p className="text-white font-medium">{audio.processingMsg}</p>
                </div>
              )}

              <div className="flex justify-between items-center mb-6">
                <div>
                  <h3 className="text-indigo-400 font-medium text-xs mb-1 uppercase tracking-widest">Workspace</h3>
                  <p className="text-white font-semibold truncate max-w-md">{audio.file?.name}</p>
                </div>
                <div className="text-right">
                  <p className="text-slate-400 text-sm font-mono">{formatTime(audio.currentTime)} / {formatTime(audio.duration)}</p>
                </div>
              </div>

              <div className="relative">
                {!audio.isMono && (
                  <>
                    <div className="absolute top-2 left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL L
                    </div>
                    <div className="absolute top-[134px] left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL R
                    </div>
                  </>
                )}
                {audio.isMono && (
                  <div className="absolute top-2 left-2 z-10 bg-emerald-500/20 text-emerald-400 backdrop-blur-md border border-emerald-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                    MONO MASTER MIX
                  </div>
                )}

                <div ref={containerRef} className="waveform-container rounded-lg bg-slate-900/50 p-2 border border-slate-700/50" />
              </div>
            </div>

            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-4 flex flex-wrap items-center justify-between gap-6 shadow-xl">
              <div className="flex items-center gap-3">
                <button 
                  onClick={togglePlay} 
                  disabled={!audio.isReady || audio.isProcessing}
                  className="w-12 h-12 flex items-center justify-center rounded-full bg-indigo-600 hover:bg-indigo-500 text-white transition-all shadow-lg shadow-indigo-600/20 disabled:opacity-50"
                >
                  {audio.isPlaying ? <Pause /> : <Play className="ml-1" />}
                </button>
                <button onClick={() => wavesurferRef.current?.stop()} className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-700 hover:bg-slate-600 text-slate-200 border border-slate-600">
                  <RotateCcw className="w-5 h-5" />
                </button>
                <div className="h-8 w-px bg-slate-700 mx-2" />
                <button 
                  onClick={toggleMono}
                  disabled={audio.isProcessing}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all text-sm font-semibold border ${
                    audio.isMono 
                    ? 'bg-emerald-600 text-white border-emerald-400 shadow-lg shadow-emerald-600/20' 
                    : 'bg-slate-700 text-slate-300 border-slate-600 hover:bg-slate-600'
                  }`}
                >
                  {audio.isProcessing ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : audio.isMono ? (
                    <Columns className="w-4 h-4" />
                  ) : (
                    <Merge className="w-4 h-4" />
                  )}
                  {audio.isMono ? 'Stereo' : 'Mix Mono'}
                </button>
              </div>

              <div className="flex items-center gap-4 flex-1 max-w-[200px]">
                <Maximize className="w-4 h-4 text-slate-500" />
                <input type="range" min="0" max="500" value={zoom} onChange={handleZoom} className="flex-1 accent-indigo-500 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
              </div>

              <div className="flex items-center gap-3 border-l border-slate-700 pl-6">
                {activeRegion ? (
                  <>
                    <button 
                      onClick={playRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-emerald-600/20 text-emerald-400 hover:bg-emerald-600/30 rounded-lg transition-all text-sm font-semibold border border-emerald-600/30"
                    >
                      <Play className="w-4 h-4" /> Listen
                    </button>
                    <button 
                      onClick={handleCut}
                      className="flex items-center gap-2 px-4 py-2 bg-rose-600/20 text-rose-400 hover:bg-rose-600/30 rounded-lg transition-all text-sm font-semibold border border-rose-600/30"
                    >
                      <Scissors className="w-4 h-4" /> Cut
                    </button>
                    <button 
                      onClick={clearRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-slate-600 rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <X className="w-4 h-4" /> Reset Selection
                    </button>
                  </>
                ) : (
                  <div className="flex items-center gap-2 text-slate-500 text-xs bg-slate-900/50 px-4 py-2 rounded-lg border border-slate-700/50 italic select-none">
                    <Scissors className="w-4 h-4" />
                    Select range to Cut or Play
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="mt-8 text-center text-slate-600 text-[10px] uppercase tracking-[0.2em] flex flex-col gap-2">
        <span>Experimental Audio Node v1.4 • Sample Summation & Splice Engine</span>
        <div className="flex justify-center gap-4 opacity-50">
          <span>{audio.isMono ? 'Mono' : 'Stereo'} Mode</span>
          <span>{formatTime(audio.duration)} Buffer</span>
        </div>
      </footer>
    </div>
  );
};

