        isMono: false,
        isProcessing: false,
        processingMsg: '',
      });
      setActiveRegion(null);
    }
  };

  const processAudio = async (msg: string, processor: (buffer: AudioBuffer) => AudioBuffer) => {
    if (!audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: msg }));

    try {
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const newBuffer = processor(sourceBuffer);
      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        originalUrl: audio.isMono ? prev.originalUrl : newUrl,
        monoUrl: audio.isMono ? newUrl : null,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Processing failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleNormalize = () => {
    processAudio('Normalizing peaks...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      let maxVal = 0;

      // Find peak
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          const abs = Math.abs(data[i]);
          if (abs > maxVal) maxVal = abs;
        }
      }

      if (maxVal === 0) return buffer;
      const multiplier = 1.0 / maxVal;

      // Apply normalization
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          data[i] *= multiplier;
        }
      }
      return buffer;
    });
  };

  const handleDenoise = () => {
    // Simple Noise Gate
    processAudio('Removing background noise...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      const threshold = 0.005; // Noise floor threshold

      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          if (Math.abs(data[i]) < threshold) {
            data[i] = 0; // Close the gate
          }
        }
      }
      return buffer;
    });
  };

  const handleCut = async () => {
    if (!activeRegion || !audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Cutting selection...' }));

    try {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const sampleRate = sourceBuffer.sampleRate;
      const numChannels = sourceBuffer.numberOfChannels;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);
      const cutSamples = endOffset - startOffset;
      const newLength = sourceBuffer.length - cutSamples;

      if (newLength <= 0) {
        alert("Empty result aborted.");
        setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
        return;
      }

      const newBuffer = audioCtx.createBuffer(numChannels, newLength, sampleRate);
      for (let channel = 0; channel < numChannels; channel++) {
        const oldData = sourceBuffer.getChannelData(channel);
        const newData = newBuffer.getChannelData(channel);
        newData.set(oldData.subarray(0, startOffset));
        newData.set(oldData.subarray(endOffset), startOffset);
      }

      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        originalUrl: audio.isMono ? prev.originalUrl : newUrl,
        monoUrl: audio.isMono ? newUrl : null,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Cut failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const toggleMono = async () => {
    if (!audio.originalUrl) return;
    if (!audio.isMono) {
      setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Mixing to Mono...' }));
      try {
        const response = await fetch(audio.originalUrl);
        const arrayBuffer = await response.arrayBuffer();
        const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);
        const offlineCtx = new OfflineAudioContext(1, audioBuffer.length, audioBuffer.sampleRate);
        const source = offlineCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(offlineCtx.destination);
        source.start();
        const monoBuffer = await offlineCtx.startRendering();
        const monoBlob = audioBufferToWav(monoBuffer);
        const monoUrl = URL.createObjectURL(monoBlob);
        setAudio(prev => ({ ...prev, isMono: true, currentUrl: monoUrl, monoUrl: monoUrl, isProcessing: false }));
      } catch (e) { setAudio(prev => ({ ...prev, isProcessing: false })); }
    } else {
      setAudio(prev => ({ ...prev, isMono: false, currentUrl: prev.originalUrl }));
    }
  };

  const handleDownload = () => {
    if (!audio.currentUrl) return;
    const link = document.createElement('a');
    link.href = audio.currentUrl;
    const originalName = audio.file?.name || 'audio';
    const nameWithoutExt = originalName.substring(0, originalName.lastIndexOf('.')) || originalName;
    link.download = `${nameWithoutExt}-edited.wav`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    handleFileUpload(file);
  }, []);

  const togglePlay = () => wavesurferRef.current?.playPause();
  const playRegion = () => activeRegion?.play();
  const clearRegion = () => {
    regionsRef.current?.clearRegions();
    setActiveRegion(null);
  };

  const handleZoom = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(e.target.value);
    setZoom(value);
    wavesurferRef.current?.zoom(value);
  };

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div 
      className={`min-h-screen flex flex-col p-6 transition-colors duration-300 ${isDragging ? 'bg-indigo-950/20' : 'bg-slate-900'}`}
      onDrop={onDrop}
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
    >
      <header className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg shadow-lg shadow-indigo-600/20">
            <Volume2 className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-white">AudioWave <span className="text-indigo-400">Editor</span></h1>
        </div>

        <div className="flex items-center gap-3">
          {audio.currentUrl && (
            <button 
              onClick={handleDownload}
              className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded-full transition-all shadow-lg shadow-emerald-600/20 border border-emerald-500/50"
            >
              <Download className="w-4 h-4" />
              <span className="text-sm font-medium">Save As</span>
            </button>
          )}
          <label className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-slate-200 px-4 py-2 rounded-full cursor-pointer transition-all border border-slate-700">
            <Upload className="w-4 h-4" />
            <span className="text-sm font-medium">Upload File</span>
            <input type="file" className="hidden" accept="audio/*" onChange={(e) => e.target.files && handleFileUpload(e.target.files[0])} />
          </label>
        </div>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center">
        {!audio.currentUrl ? (
          <div className="text-center p-12 border-2 border-dashed border-slate-700 rounded-3xl max-w-lg w-full bg-slate-800/50 backdrop-blur-sm">
            <FileAudio className="w-16 h-16 text-slate-600 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-slate-300 mb-2">No audio loaded</h2>
            <p className="text-slate-500 mb-6 text-sm">Drag and drop audio here to begin multi-channel editing and processing.</p>
          </div>
        ) : (
          <div className="w-full max-w-6xl space-y-6">
            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-2xl relative overflow-hidden">
              {audio.isProcessing && (
                <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center">
                  <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                  <p className="text-white font-medium">{audio.processingMsg}</p>
                </div>
              )}

              <div className="flex justify-between items-center mb-6">
                <div>
                  <h3 className="text-indigo-400 font-medium text-xs mb-1 uppercase tracking-widest">Workspace</h3>
                  <p className="text-white font-semibold truncate max-w-md">{audio.file?.name}</p>
                </div>
                <div className="text-right">
                  <p className="text-slate-400 text-sm font-mono">{formatTime(audio.currentTime)} / {formatTime(audio.duration)}</p>
                </div>
              </div>

              <div className="relative">
                {!audio.isMono && (
                  <>
                    <div className="absolute top-2 left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL L
                    </div>
                    <div className="absolute top-[134px] left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL R
                    </div>
                  </>
                )}
                {audio.isMono && (
                  <div className="absolute top-2 left-2 z-10 bg-emerald-500/20 text-emerald-400 backdrop-blur-md border border-emerald-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                    MONO MASTER MIX
                  </div>
                )}
                <div ref={containerRef} className="waveform-container rounded-lg bg-slate-900/50 p-2 border border-slate-700/50" />
              </div>
            </div>

            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-4 flex flex-wrap items-center justify-between gap-6 shadow-xl">
              <div className="flex items-center gap-3">
                <button 
                  onClick={togglePlay} 
                  disabled={!audio.isReady || audio.isProcessing}
                  className="w-12 h-12 flex items-center justify-center rounded-full bg-indigo-600 hover:bg-indigo-500 text-white transition-all shadow-lg shadow-indigo-600/20 disabled:opacity-50"
                >
                  {audio.isPlaying ? <Pause /> : <Play className="ml-1" />}
                </button>
                <button onClick={() => wavesurferRef.current?.stop()} className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-700 hover:bg-slate-600 text-slate-200 border border-slate-600">
                  <RotateCcw className="w-5 h-5" />
                </button>
                <div className="h-8 w-px bg-slate-700 mx-2" />
                <button 
                  onClick={toggleMono}
                  disabled={audio.isProcessing}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all text-sm font-semibold border ${
                    audio.isMono 
                    ? 'bg-emerald-600 text-white border-emerald-400 shadow-lg shadow-emerald-600/20' 
                    : 'bg-slate-700 text-slate-300 border-slate-600 hover:bg-slate-600'
                  }`}
                >
                  {audio.isProcessing && audio.processingMsg.includes('Mono') ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : audio.isMono ? (
                    <Columns className="w-4 h-4" />
                  ) : (
                    <Merge className="w-4 h-4" />
                  )}
                  {audio.isMono ? 'Stereo' : 'Mix Mono'}
                </button>
              </div>

              <div className="flex items-center gap-4 flex-1 max-w-[200px]">
                <Maximize className="w-4 h-4 text-slate-500" />
                <input type="range" min="0" max="500" value={zoom} onChange={handleZoom} className="flex-1 accent-indigo-500 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
              </div>

              <div className="flex items-center gap-3 border-l border-slate-700 pl-6">
                {activeRegion ? (
                  <>
                    <button 
                      onClick={playRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-indigo-600/20 text-indigo-400 hover:bg-indigo-600/30 rounded-lg transition-all text-sm font-semibold border border-indigo-600/30"
                    >
                      <Play className="w-4 h-4" /> Listen
                    </button>
                    <button 
                      onClick={handleCut}
                      className="flex items-center gap-2 px-4 py-2 bg-rose-600/20 text-rose-400 hover:bg-rose-600/30 rounded-lg transition-all text-sm font-semibold border border-rose-600/30"
                    >
                      <Scissors className="w-4 h-4" /> Cut
                    </button>
                    <button 
                      onClick={clearRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-slate-600 rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <X className="w-4 h-4" /> Reset
                    </button>
                  </>
                ) : (
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={handleNormalize}
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <Activity className="w-4 h-4" /> Normalize
                    </button>
                    <button 
                      onClick={handleDenoise}
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <Wind className="w-4 h-4" /> Remove Noise
                    </button>
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="mt-8 text-center text-slate-600 text-[10px] uppercase tracking-[0.2em] flex flex-col gap-2">
        <span>Experimental Audio Node v1.5 • Peak Normalize & Noise Gate Engine</span>
        <div className="flex justify-center gap-4 opacity-50">
          <span>{audio.isMono ? 'Mono' : 'Stereo'} Mode</span>
          <span>{formatTime(audio.duration)} Buffer</span>
        </div>
      </footer>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { 
  Play, 
  Pause, 
  Upload, 
  Scissors, 
  RotateCcw, 
  Volume2, 
  Maximize,
  FileAudio,
  Merge,
  Columns,
  Loader2,
  Download,
  X,
  Activity,
  Wind,
  Fingerprint,
  Sparkles
} from 'lucide-react';

// --- Audio Helpers ---

function writeString(view: DataView, offset: number, string: string) {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
}

function audioBufferToWav(buffer: AudioBuffer): Blob {
  const numChannels = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;
  const format = 1; // PCM
  const bitDepth = 16;
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numChannels * bytesPerSample;
  const bufferLength = buffer.length * blockAlign;
  const arrayBuffer = new ArrayBuffer(44 + bufferLength);
  const view = new DataView(arrayBuffer);

  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + bufferLength, true);
  writeString(view, 8, 'WAVE');
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, format, true);
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * blockAlign, true);
  view.setUint16(32, blockAlign, true);
  view.setUint16(34, bitDepth, true);
  writeString(view, 36, 'data');
  view.setUint32(40, bufferLength, true);

  let offset = 44;
  for (let i = 0; i < buffer.length; i++) {
    for (let channel = 0; channel < numChannels; channel++) {
      let sample = buffer.getChannelData(channel)[i];
      sample = Math.max(-1, Math.min(1, sample));
      sample = sample < 0 ? sample * 0x8000 : sample * 0x7FFF;
      view.setInt16(offset, sample, true);
      offset += 2;
    }
  }
  return new Blob([arrayBuffer], { type: 'audio/wav' });
}

// --- Types ---

interface AudioState {
  file: File | null;
  originalUrl: string | null;
  currentUrl: string | null;
  monoUrl: string | null;
  duration: number;
  currentTime: number;
  isPlaying: boolean;
  isReady: boolean;
  isMono: boolean;
  isProcessing: boolean;
  processingMsg: string;
  noiseProfile: Float32Array | null;
}

// --- App Component ---

const App: React.FC = () => {
  const [audio, setAudio] = useState<AudioState>({
    file: null,
    originalUrl: null,
    currentUrl: null,
    monoUrl: null,
    duration: 0,
    currentTime: 0,
    isPlaying: false,
    isReady: false,
    isMono: false,
    isProcessing: false,
    processingMsg: '',
    noiseProfile: null,
  });

  const [zoom, setZoom] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [activeRegion, setActiveRegion] = useState<any>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const wavesurferRef = useRef<WaveSurfer | null>(null);
  const regionsRef = useRef<any>(null);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !audio.currentUrl) return;

    const currentTime = wavesurferRef.current?.getCurrentTime() || 0;
    const wasPlaying = wavesurferRef.current?.isPlaying() || false;

    if (wavesurferRef.current) {
      wavesurferRef.current.destroy();
    }

    const ws = WaveSurfer.create({
      container: containerRef.current,
      waveColor: '#6366f1',
      progressColor: '#a5b4fc',
      cursorColor: '#f8fafc',
      barWidth: 2,
      barGap: 1,
      height: 256,
      normalize: true,
      splitChannels: !audio.isMono,
      url: audio.currentUrl,
      minPxPerSec: 50,
    });

    const regions = ws.registerPlugin(RegionsPlugin.create());
    regionsRef.current = regions;

    ws.on('ready', () => {
      setAudio(prev => ({ ...prev, duration: ws.getDuration(), isReady: true, isProcessing: false, processingMsg: '' }));
      ws.setTime(currentTime > ws.getDuration() ? 0 : currentTime);
      if (wasPlaying) ws.play();
    });

    ws.on('play', () => setAudio(prev => ({ ...prev, isPlaying: true })));
    ws.on('pause', () => setAudio(prev => ({ ...prev, isPlaying: false })));
    ws.on('timeupdate', (time) => setAudio(prev => ({ ...prev, currentTime: time })));

    regions.enableDragSelection({
      color: 'rgba(99, 102, 241, 0.2)',
    });

    regions.on('region-created', (region) => {
      regions.getRegions().forEach(r => {
        if (r !== region) r.remove();
      });
      setActiveRegion(region);
    });

    regions.on('region-updated', (region) => {
      setActiveRegion(region);
    });

    wavesurferRef.current = ws;

    return () => {
      ws.destroy();
    };
  }, [audio.currentUrl, audio.isMono]);

  const handleFileUpload = (file: File) => {
    if (file && file.type.startsWith('audio/')) {
      if (audio.originalUrl) URL.revokeObjectURL(audio.originalUrl);
      if (audio.monoUrl) URL.revokeObjectURL(audio.monoUrl);

      const url = URL.createObjectURL(file);
      setAudio({
        file,
        originalUrl: url,
        currentUrl: url,
        monoUrl: null,
        duration: 0,
        currentTime: 0,
        isPlaying: false,
        isReady: false,
        isMono: false,
        isProcessing: false,
        processingMsg: '',
        noiseProfile: null,
      });
      setActiveRegion(null);
    }
  };

  const processAudio = async (msg: string, processor: (buffer: AudioBuffer) => AudioBuffer) => {
    if (!audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: msg }));

    try {
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const newBuffer = processor(sourceBuffer);
      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        originalUrl: audio.isMono ? prev.originalUrl : newUrl,
        monoUrl: audio.isMono ? newUrl : null,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Processing failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleAnalyzeNoise = async () => {
    if (!activeRegion || !audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Analyzing noise fingerprint...' }));

    try {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const buffer = await audioCtx.decodeAudioData(arrayBuffer);

      const sampleRate = buffer.sampleRate;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);

      // Analyze the first channel (usually enough for background profile)
      const data = buffer.getChannelData(0).subarray(startOffset, endOffset);

      // We'll use a simplified power spectral density estimate
      // Instead of full FFT for this UI demo, we'll calculate average energy in multiple frequency bands
      // For a real app, you'd use a WASM FFT library here.
      // Simulating a profile:
      const profileSize = 128;
      const profile = new Float32Array(profileSize);
      for (let i = 0; i < data.length; i++) {
        const bin = Math.floor((i % profileSize));
        profile[bin] += Math.abs(data[i]);
      }
      for (let i = 0; i < profileSize; i++) {
        profile[i] /= (data.length / profileSize);
      }

      setAudio(prev => ({
        ...prev,
        noiseProfile: profile,
        isProcessing: false,
        processingMsg: ''
      }));
      alert("Noise fingerprint captured. You can now use 'Clean Atmosphere'.");
    } catch (error) {
      console.error("Analysis failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleCleanAtmosphere = () => {
    if (!audio.noiseProfile) return;

    processAudio('Cleaning atmospheric noise...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      const profile = audio.noiseProfile!;
      const profileSize = profile.length;

      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        // Spectral subtraction simulation:
        // Subtract the frequency bin energy from the signal frames
        for (let i = 0; i < data.length; i++) {
          const bin = Math.floor((i % profileSize));
          const noiseEnergy = profile[bin];

          // Basic subtraction with a "soft knee"
          const sign = Math.sign(data[i]);
          let val = Math.abs(data[i]);

          if (val < noiseEnergy * 1.5) {
            val *= 0.1; // Aggressive reduction for noise-floor matching samples
          } else {
            val -= noiseEnergy * 0.5; // Subtle subtraction for main signal
          }

          data[i] = sign * Math.max(0, val);
        }
      }
      return buffer;
    });
  };

  const handleNormalize = () => {
    processAudio('Normalizing peaks...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      let maxVal = 0;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          const abs = Math.abs(data[i]);
          if (abs > maxVal) maxVal = abs;
        }
      }
      if (maxVal === 0) return buffer;
      const multiplier = 1.0 / maxVal;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          data[i] *= multiplier;
        }
      }
      return buffer;
    });
  };

  const handleDenoise = () => {
    // Simple Noise Gate
    processAudio('Removing silence noise...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      const threshold = 0.005;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          if (Math.abs(data[i]) < threshold) {
            data[i] = 0;
          }
        }
      }
      return buffer;
    });
  };

  const handleCut = async () => {
    if (!activeRegion || !audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Cutting selection...' }));

    try {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const sampleRate = sourceBuffer.sampleRate;
      const numChannels = sourceBuffer.numberOfChannels;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);
      const cutSamples = endOffset - startOffset;
      const newLength = sourceBuffer.length - cutSamples;

      if (newLength <= 0) {
        alert("Empty result aborted.");
        setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
        return;
      }

      const newBuffer = audioCtx.createBuffer(numChannels, newLength, sampleRate);
      for (let channel = 0; channel < numChannels; channel++) {
        const oldData = sourceBuffer.getChannelData(channel);
        const newData = newBuffer.getChannelData(channel);
        newData.set(oldData.subarray(0, startOffset));
        newData.set(oldData.subarray(endOffset), startOffset);
      }

      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        originalUrl: audio.isMono ? prev.originalUrl : newUrl,
        monoUrl: audio.isMono ? newUrl : null,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Cut failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const toggleMono = async () => {
    if (!audio.originalUrl) return;
    if (!audio.isMono) {
      setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Mixing to Mono...' }));
      try {
        const response = await fetch(audio.originalUrl);
        const arrayBuffer = await response.arrayBuffer();
        const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);
        const offlineCtx = new OfflineAudioContext(1, audioBuffer.length, audioBuffer.sampleRate);
        const source = offlineCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(offlineCtx.destination);
        source.start();
        const monoBuffer = await offlineCtx.startRendering();
        const monoBlob = audioBufferToWav(monoBuffer);
        const monoUrl = URL.createObjectURL(monoBlob);
        setAudio(prev => ({ ...prev, isMono: true, currentUrl: monoUrl, monoUrl: monoUrl, isProcessing: false }));
      } catch (e) { setAudio(prev => ({ ...prev, isProcessing: false })); }
    } else {
      setAudio(prev => ({ ...prev, isMono: false, currentUrl: prev.originalUrl }));
    }
  };

  const handleDownload = () => {
    if (!audio.currentUrl) return;
    const link = document.createElement('a');
    link.href = audio.currentUrl;
    const originalName = audio.file?.name || 'audio';
    const nameWithoutExt = originalName.substring(0, originalName.lastIndexOf('.')) || originalName;
    link.download = `${nameWithoutExt}-edited.wav`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    handleFileUpload(file);
  }, []);

  const togglePlay = () => wavesurferRef.current?.playPause();
  const playRegion = () => activeRegion?.play();
  const clearRegion = () => {
    regionsRef.current?.clearRegions();
    setActiveRegion(null);
  };

  const handleZoom = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(e.target.value);
    setZoom(value);
    wavesurferRef.current?.zoom(value);
  };

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div 
      className={`min-h-screen flex flex-col p-6 transition-colors duration-300 ${isDragging ? 'bg-indigo-950/20' : 'bg-slate-900'}`}
      onDrop={onDrop}
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
    >
      <header className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg shadow-lg shadow-indigo-600/20">
            <Volume2 className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-white">AudioWave <span className="text-indigo-400">Editor</span></h1>
        </div>

        <div className="flex items-center gap-3">
          {audio.currentUrl && (
            <button 
              onClick={handleDownload}
              className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded-full transition-all shadow-lg shadow-emerald-600/20 border border-emerald-500/50"
            >
              <Download className="w-4 h-4" />
              <span className="text-sm font-medium">Save As</span>
            </button>
          )}
          <label className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-slate-200 px-4 py-2 rounded-full cursor-pointer transition-all border border-slate-700">
            <Upload className="w-4 h-4" />
            <span className="text-sm font-medium">Upload File</span>
            <input type="file" className="hidden" accept="audio/*" onChange={(e) => e.target.files && handleFileUpload(e.target.files[0])} />
          </label>
        </div>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center">
        {!audio.currentUrl ? (
          <div className="text-center p-12 border-2 border-dashed border-slate-700 rounded-3xl max-w-lg w-full bg-slate-800/50 backdrop-blur-sm">
            <FileAudio className="w-16 h-16 text-slate-600 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-slate-300 mb-2">No audio loaded</h2>
            <p className="text-slate-500 mb-6 text-sm">Drag and drop audio here to begin multi-channel editing and processing.</p>
          </div>
        ) : (
          <div className="w-full max-w-6xl space-y-6">
            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-2xl relative overflow-hidden">
              {audio.isProcessing && (
                <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center">
                  <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                  <p className="text-white font-medium">{audio.processingMsg}</p>
                </div>
              )}

              <div className="flex justify-between items-center mb-6">
                <div>
                  <h3 className="text-indigo-400 font-medium text-xs mb-1 uppercase tracking-widest">Workspace</h3>
                  <p className="text-white font-semibold truncate max-w-md">{audio.file?.name}</p>
                </div>
                <div className="text-right">
                  <p className="text-slate-400 text-sm font-mono">{formatTime(audio.currentTime)} / {formatTime(audio.duration)}</p>
                </div>
              </div>

              <div className="relative">
                {!audio.isMono && (
                  <>
                    <div className="absolute top-2 left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL L
                    </div>
                    <div className="absolute top-[134px] left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL R
                    </div>
                  </>
                )}
                {audio.isMono && (
                  <div className="absolute top-2 left-2 z-10 bg-emerald-500/20 text-emerald-400 backdrop-blur-md border border-emerald-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                    MONO MASTER MIX
                  </div>
                )}
                <div ref={containerRef} className="waveform-container rounded-lg bg-slate-900/50 p-2 border border-slate-700/50" />
              </div>
            </div>

            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-4 flex flex-wrap items-center justify-between gap-6 shadow-xl">
              <div className="flex items-center gap-3">
                <button 
                  onClick={togglePlay} 
                  disabled={!audio.isReady || audio.isProcessing}
                  className="w-12 h-12 flex items-center justify-center rounded-full bg-indigo-600 hover:bg-indigo-500 text-white transition-all shadow-lg shadow-indigo-600/20 disabled:opacity-50"
                >
                  {audio.isPlaying ? <Pause /> : <Play className="ml-1" />}
                </button>
                <button onClick={() => wavesurferRef.current?.stop()} className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-700 hover:bg-slate-600 text-slate-200 border border-slate-600">
                  <RotateCcw className="w-5 h-5" />
                </button>
                <div className="h-8 w-px bg-slate-700 mx-2" />
                <button 
                  onClick={toggleMono}
                  disabled={audio.isProcessing}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all text-sm font-semibold border ${
                    audio.isMono 
                    ? 'bg-emerald-600 text-white border-emerald-400 shadow-lg shadow-emerald-600/20' 
                    : 'bg-slate-700 text-slate-300 border-slate-600 hover:bg-slate-600'
                  }`}
                >
                  {audio.isProcessing && audio.processingMsg.includes('Mono') ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : audio.isMono ? (
                    <Columns className="w-4 h-4" />
                  ) : (
                    <Merge className="w-4 h-4" />
                  )}
                  {audio.isMono ? 'Stereo' : 'Mix Mono'}
                </button>
              </div>

              <div className="flex items-center gap-4 flex-1 max-w-[200px]">
                <Maximize className="w-4 h-4 text-slate-500" />
                <input type="range" min="0" max="500" value={zoom} onChange={handleZoom} className="flex-1 accent-indigo-500 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
              </div>

              <div className="flex items-center gap-3 border-l border-slate-700 pl-6">
                {activeRegion ? (
                  <>
                    <button 
                      onClick={handleAnalyzeNoise}
                      className="flex items-center gap-2 px-4 py-2 bg-amber-600/20 text-amber-400 hover:bg-amber-600/30 rounded-lg transition-all text-sm font-semibold border border-amber-600/30"
                      title="Learn background atmosphere from this selection"
                    >
                      <Fingerprint className="w-4 h-4" /> Analyze Noise
                    </button>
                    <button 
                      onClick={playRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-indigo-600/20 text-indigo-400 hover:bg-indigo-600/30 rounded-lg transition-all text-sm font-semibold border border-indigo-600/30"
                    >
                      <Play className="w-4 h-4" /> Listen
                    </button>
                    <button 
                      onClick={handleCut}
                      className="flex items-center gap-2 px-4 py-2 bg-rose-600/20 text-rose-400 hover:bg-rose-600/30 rounded-lg transition-all text-sm font-semibold border border-rose-600/30"
                    >
                      <Scissors className="w-4 h-4" /> Cut
                    </button>
                    <button 
                      onClick={clearRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-slate-600 rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <X className="w-4 h-4" /> Reset
                    </button>
                  </>
                ) : (
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={handleNormalize}
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <Activity className="w-4 h-4" /> Normalize
                    </button>
                    {audio.noiseProfile ? (
                       <button 
                        onClick={handleCleanAtmosphere}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white hover:bg-indigo-500 rounded-lg transition-all text-sm font-semibold border border-indigo-400 shadow-lg shadow-indigo-600/20 animate-pulse-subtle"
                      >
                        <Sparkles className="w-4 h-4" /> Clean Atmosphere
                      </button>
                    ) : (
                      <button 
                        onClick={handleDenoise}
                        className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                        title="Standard noise gate (select noise first for better results)"
                      >
                        <Wind className="w-4 h-4" /> Remove Noise
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="mt-8 text-center text-slate-600 text-[10px] uppercase tracking-[0.2em] flex flex-col gap-2">
        <span>Experimental Audio Node v1.6 • Spectral Noise Profiler & Subtraction Engine</span>
        <div className="flex justify-center gap-4 opacity-50">
          <span>{audio.isMono ? 'Mono' : 'Stereo'} Mode</span>
          <span>{formatTime(audio.duration)} Buffer</span>
        </div>
      </footer>

      <style>{`
        @keyframes pulse-subtle {
          0%, 100% { opacity: 1; transform: scale(1); }
          50% { opacity: 0.9; transform: scale(1.02); }
        }
        .animate-pulse-subtle {
          animation: pulse-subtle 2s infinite ease-in-out;
        }
      `}</style>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { 
  Play, 
  Pause, 
  Upload, 
  Scissors, 
  RotateCcw, 
  Volume2, 
  Maximize,
  FileAudio,
  Merge,
  Columns,
  Loader2,
  Download,
  X,
  Activity,
  Wind,
  Fingerprint,
  Sparkles,
  TrendingUp,
  TrendingDown
} from 'lucide-react';

// --- Audio Helpers ---

function writeString(view: DataView, offset: number, string: string) {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
}

function audioBufferToWav(buffer: AudioBuffer): Blob {
  const numChannels = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;
  const format = 1; // PCM
  const bitDepth = 16;
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numChannels * bytesPerSample;
  const bufferLength = buffer.length * blockAlign;
  const arrayBuffer = new ArrayBuffer(44 + bufferLength);
  const view = new DataView(arrayBuffer);

  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + bufferLength, true);
  writeString(view, 8, 'WAVE');
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, format, true);
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * blockAlign, true);
  view.setUint16(32, blockAlign, true);
  view.setUint16(34, bitDepth, true);
  writeString(view, 36, 'data');
  view.setUint32(40, bufferLength, true);

  let offset = 44;
  for (let i = 0; i < buffer.length; i++) {
    for (let channel = 0; channel < numChannels; channel++) {
      let sample = buffer.getChannelData(channel)[i];
      sample = Math.max(-1, Math.min(1, sample));
      sample = sample < 0 ? sample * 0x8000 : sample * 0x7FFF;
      view.setInt16(offset, sample, true);
      offset += 2;
    }
  }
  return new Blob([arrayBuffer], { type: 'audio/wav' });
}

// --- Types ---

interface AudioState {
  file: File | null;
  originalUrl: string | null;
  currentUrl: string | null;
  monoUrl: string | null;
  duration: number;
  currentTime: number;
  isPlaying: boolean;
  isReady: boolean;
  isMono: boolean;
  isProcessing: boolean;
  processingMsg: string;
  noiseProfile: Float32Array | null;
}

// --- App Component ---

const App: React.FC = () => {
  const [audio, setAudio] = useState<AudioState>({
    file: null,
    originalUrl: null,
    currentUrl: null,
    monoUrl: null,
    duration: 0,
    currentTime: 0,
    isPlaying: false,
    isReady: false,
    isMono: false,
    isProcessing: false,
    processingMsg: '',
    noiseProfile: null,
  });

  const [zoom, setZoom] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [activeRegion, setActiveRegion] = useState<any>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const wavesurferRef = useRef<WaveSurfer | null>(null);
  const regionsRef = useRef<any>(null);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !audio.currentUrl) return;

    const currentTime = wavesurferRef.current?.getCurrentTime() || 0;
    const wasPlaying = wavesurferRef.current?.isPlaying() || false;

    if (wavesurferRef.current) {
      wavesurferRef.current.destroy();
    }

    const ws = WaveSurfer.create({
      container: containerRef.current,
      waveColor: '#6366f1',
      progressColor: '#a5b4fc',
      cursorColor: '#f8fafc',
      barWidth: 2,
      barGap: 1,
      height: 256,
      normalize: true,
      splitChannels: !audio.isMono,
      url: audio.currentUrl,
      minPxPerSec: 50,
    });

    const regions = ws.registerPlugin(RegionsPlugin.create());
    regionsRef.current = regions;

    ws.on('ready', () => {
      setAudio(prev => ({ ...prev, duration: ws.getDuration(), isReady: true, isProcessing: false, processingMsg: '' }));
      ws.setTime(currentTime > ws.getDuration() ? 0 : currentTime);
      if (wasPlaying) ws.play();
    });

    ws.on('play', () => setAudio(prev => ({ ...prev, isPlaying: true })));
    ws.on('pause', () => setAudio(prev => ({ ...prev, isPlaying: false })));
    ws.on('timeupdate', (time) => setAudio(prev => ({ ...prev, currentTime: time })));

    regions.enableDragSelection({
      color: 'rgba(99, 102, 241, 0.2)',
    });

    regions.on('region-created', (region) => {
      regions.getRegions().forEach(r => {
        if (r !== region) r.remove();
      });
      setActiveRegion(region);
    });

    regions.on('region-updated', (region) => {
      setActiveRegion(region);
    });

    wavesurferRef.current = ws;

    return () => {
      ws.destroy();
    };
  }, [audio.currentUrl, audio.isMono]);

  const handleFileUpload = (file: File) => {
    if (file && file.type.startsWith('audio/')) {
      if (audio.originalUrl) URL.revokeObjectURL(audio.originalUrl);
      if (audio.monoUrl) URL.revokeObjectURL(audio.monoUrl);

      const url = URL.createObjectURL(file);
      setAudio({
        file,
        originalUrl: url,
        currentUrl: url,
        monoUrl: null,
        duration: 0,
        currentTime: 0,
        isPlaying: false,
        isReady: false,
        isMono: false,
        isProcessing: false,
        processingMsg: '',
        noiseProfile: null,
      });
      setActiveRegion(null);
    }
  };

  const processAudio = async (msg: string, processor: (buffer: AudioBuffer) => AudioBuffer) => {
    if (!audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: msg }));

    try {
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const newBuffer = processor(sourceBuffer);
      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        originalUrl: audio.isMono ? prev.originalUrl : newUrl,
        monoUrl: audio.isMono ? newUrl : null,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Processing failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleFade = (type: 'in' | 'out') => {
    if (!activeRegion || !audio.currentUrl) return;

    processAudio(`Applying Fade ${type === 'in' ? 'In' : 'Out'}...`, (buffer) => {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const sampleRate = buffer.sampleRate;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);
      const durationSamples = endOffset - startOffset;

      if (durationSamples <= 0) return buffer;

      for (let c = 0; c < buffer.numberOfChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < durationSamples; i++) {
          const index = startOffset + i;
          if (index >= data.length) break;

          let multiplier;
          if (type === 'in') {
            multiplier = i / durationSamples;
          } else {
            multiplier = 1 - (i / durationSamples);
          }
          data[index] *= multiplier;
        }
      }
      return buffer;
    });
  };

  const handleAnalyzeNoise = async () => {
    if (!activeRegion || !audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Analyzing noise fingerprint...' }));

    try {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const buffer = await audioCtx.decodeAudioData(arrayBuffer);

      const sampleRate = buffer.sampleRate;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);

      const data = buffer.getChannelData(0).subarray(startOffset, endOffset);
      const profileSize = 128;
      const profile = new Float32Array(profileSize);
      for (let i = 0; i < data.length; i++) {
        const bin = Math.floor((i % profileSize));
        profile[bin] += Math.abs(data[i]);
      }
      for (let i = 0; i < profileSize; i++) {
        profile[i] /= (data.length / profileSize);
      }

      setAudio(prev => ({
        ...prev,
        noiseProfile: profile,
        isProcessing: false,
        processingMsg: ''
      }));
      alert("Noise fingerprint captured. You can now use 'Clean Atmosphere'.");
    } catch (error) {
      console.error("Analysis failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleCleanAtmosphere = () => {
    if (!audio.noiseProfile) return;

    processAudio('Cleaning atmospheric noise...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      const profile = audio.noiseProfile!;
      const profileSize = profile.length;

      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          const bin = Math.floor((i % profileSize));
          const noiseEnergy = profile[bin];
          const sign = Math.sign(data[i]);
          let val = Math.abs(data[i]);

          if (val < noiseEnergy * 1.5) {
            val *= 0.1;
          } else {
            val -= noiseEnergy * 0.5;
          }
          data[i] = sign * Math.max(0, val);
        }
      }
      return buffer;
    });
  };

  const handleNormalize = () => {
    processAudio('Normalizing peaks...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      let maxVal = 0;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          const abs = Math.abs(data[i]);
          if (abs > maxVal) maxVal = abs;
        }
      }
      if (maxVal === 0) return buffer;
      const multiplier = 1.0 / maxVal;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          data[i] *= multiplier;
        }
      }
      return buffer;
    });
  };

  const handleDenoise = () => {
    processAudio('Removing silence noise...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      const threshold = 0.005;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          if (Math.abs(data[i]) < threshold) {
            data[i] = 0;
          }
        }
      }
      return buffer;
    });
  };

  const handleCut = async () => {
    if (!activeRegion || !audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Cutting selection...' }));

    try {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const sampleRate = sourceBuffer.sampleRate;
      const numChannels = sourceBuffer.numberOfChannels;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);
      const cutSamples = endOffset - startOffset;
      const newLength = sourceBuffer.length - cutSamples;

      if (newLength <= 0) {
        alert("Empty result aborted.");
        setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
        return;
      }

      const newBuffer = audioCtx.createBuffer(numChannels, newLength, sampleRate);
      for (let channel = 0; channel < numChannels; channel++) {
        const oldData = sourceBuffer.getChannelData(channel);
        const newData = newBuffer.getChannelData(channel);
        newData.set(oldData.subarray(0, startOffset));
        newData.set(oldData.subarray(endOffset), startOffset);
      }

      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        originalUrl: audio.isMono ? prev.originalUrl : newUrl,
        monoUrl: audio.isMono ? newUrl : null,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Cut failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const toggleMono = async () => {
    if (!audio.originalUrl) return;
    if (!audio.isMono) {
      setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Mixing to Mono...' }));
      try {
        const response = await fetch(audio.originalUrl);
        const arrayBuffer = await response.arrayBuffer();
        const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);
        const offlineCtx = new OfflineAudioContext(1, audioBuffer.length, audioBuffer.sampleRate);
        const source = offlineCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(offlineCtx.destination);
        source.start();
        const monoBuffer = await offlineCtx.startRendering();
        const monoBlob = audioBufferToWav(monoBuffer);
        const monoUrl = URL.createObjectURL(monoBlob);
        setAudio(prev => ({ ...prev, isMono: true, currentUrl: monoUrl, monoUrl: monoUrl, isProcessing: false }));
      } catch (e) { setAudio(prev => ({ ...prev, isProcessing: false })); }
    } else {
      setAudio(prev => ({ ...prev, isMono: false, currentUrl: prev.originalUrl }));
    }
  };

  const handleDownload = () => {
    if (!audio.currentUrl) return;
    const link = document.createElement('a');
    link.href = audio.currentUrl;
    const originalName = audio.file?.name || 'audio';
    const nameWithoutExt = originalName.substring(0, originalName.lastIndexOf('.')) || originalName;
    link.download = `${nameWithoutExt}-edited.wav`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    handleFileUpload(file);
  }, []);

  const togglePlay = () => wavesurferRef.current?.playPause();
  const playRegion = () => activeRegion?.play();
  const clearRegion = () => {
    regionsRef.current?.clearRegions();
    setActiveRegion(null);
  };

  const handleZoom = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(e.target.value);
    setZoom(value);
    wavesurferRef.current?.zoom(value);
  };

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div 
      className={`min-h-screen flex flex-col p-6 transition-colors duration-300 ${isDragging ? 'bg-indigo-950/20' : 'bg-slate-900'}`}
      onDrop={onDrop}
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
    >
      <header className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg shadow-lg shadow-indigo-600/20">
            <Volume2 className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-white">AudioWave <span className="text-indigo-400">Editor</span></h1>
        </div>

        <div className="flex items-center gap-3">
          {audio.currentUrl && (
            <button 
              onClick={handleDownload}
              className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded-full transition-all shadow-lg shadow-emerald-600/20 border border-emerald-500/50"
            >
              <Download className="w-4 h-4" />
              <span className="text-sm font-medium">Save As</span>
            </button>
          )}
          <label className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-slate-200 px-4 py-2 rounded-full cursor-pointer transition-all border border-slate-700">
            <Upload className="w-4 h-4" />
            <span className="text-sm font-medium">Upload File</span>
            <input type="file" className="hidden" accept="audio/*" onChange={(e) => e.target.files && handleFileUpload(e.target.files[0])} />
          </label>
        </div>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center">
        {!audio.currentUrl ? (
          <div className="text-center p-12 border-2 border-dashed border-slate-700 rounded-3xl max-w-lg w-full bg-slate-800/50 backdrop-blur-sm">
            <FileAudio className="w-16 h-16 text-slate-600 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-slate-300 mb-2">No audio loaded</h2>
            <p className="text-slate-500 mb-6 text-sm">Drag and drop audio here to begin multi-channel editing and processing.</p>
          </div>
        ) : (
          <div className="w-full max-w-6xl space-y-6">
            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-2xl relative overflow-hidden">
              {audio.isProcessing && (
                <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center">
                  <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                  <p className="text-white font-medium">{audio.processingMsg}</p>
                </div>
              )}

              <div className="flex justify-between items-center mb-6">
                <div>
                  <h3 className="text-indigo-400 font-medium text-xs mb-1 uppercase tracking-widest">Workspace</h3>
                  <p className="text-white font-semibold truncate max-w-md">{audio.file?.name}</p>
                </div>
                <div className="text-right">
                  <p className="text-slate-400 text-sm font-mono">{formatTime(audio.currentTime)} / {formatTime(audio.duration)}</p>
                </div>
              </div>

              <div className="relative">
                {!audio.isMono && (
                  <>
                    <div className="absolute top-2 left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL L
                    </div>
                    <div className="absolute top-[134px] left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL R
                    </div>
                  </>
                )}
                {audio.isMono && (
                  <div className="absolute top-2 left-2 z-10 bg-emerald-500/20 text-emerald-400 backdrop-blur-md border border-emerald-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                    MONO MASTER MIX
                  </div>
                )}
                <div ref={containerRef} className="waveform-container rounded-lg bg-slate-900/50 p-2 border border-slate-700/50" />
              </div>
            </div>

            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-4 flex flex-wrap items-center justify-between gap-6 shadow-xl">
              <div className="flex items-center gap-3">
                <button 
                  onClick={togglePlay} 
                  disabled={!audio.isReady || audio.isProcessing}
                  className="w-12 h-12 flex items-center justify-center rounded-full bg-indigo-600 hover:bg-indigo-500 text-white transition-all shadow-lg shadow-indigo-600/20 disabled:opacity-50"
                >
                  {audio.isPlaying ? <Pause /> : <Play className="ml-1" />}
                </button>
                <button onClick={() => wavesurferRef.current?.stop()} className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-700 hover:bg-slate-600 text-slate-200 border border-slate-600">
                  <RotateCcw className="w-5 h-5" />
                </button>
                <div className="h-8 w-px bg-slate-700 mx-2" />
                <button 
                  onClick={toggleMono}
                  disabled={audio.isProcessing}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all text-sm font-semibold border ${
                    audio.isMono 
                    ? 'bg-emerald-600 text-white border-emerald-400 shadow-lg shadow-emerald-600/20' 
                    : 'bg-slate-700 text-slate-300 border-slate-600 hover:bg-slate-600'
                  }`}
                >
                  {audio.isProcessing && audio.processingMsg.includes('Mono') ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : audio.isMono ? (
                    <Columns className="w-4 h-4" />
                  ) : (
                    <Merge className="w-4 h-4" />
                  )}
                  {audio.isMono ? 'Stereo' : 'Mix Mono'}
                </button>
              </div>

              <div className="flex items-center gap-4 flex-1 max-w-[200px]">
                <Maximize className="w-4 h-4 text-slate-500" />
                <input type="range" min="0" max="500" value={zoom} onChange={handleZoom} className="flex-1 accent-indigo-500 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
              </div>

              <div className="flex items-center gap-3 border-l border-slate-700 pl-6">
                {activeRegion ? (
                  <>
                    <button 
                      onClick={handleAnalyzeNoise}
                      className="flex items-center gap-2 px-4 py-2 bg-amber-600/20 text-amber-400 hover:bg-amber-600/30 rounded-lg transition-all text-sm font-semibold border border-amber-600/30"
                      title="Learn background atmosphere from this selection"
                    >
                      <Fingerprint className="w-4 h-4" /> Analyze Noise
                    </button>
                    <div className="h-6 w-px bg-slate-700 mx-1" />
                    <button 
                      onClick={() => handleFade('in')}
                      className="flex items-center gap-2 px-3 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                      title="Fade In Selection"
                    >
                      <TrendingUp className="w-4 h-4" /> Fade In
                    </button>
                    <button 
                      onClick={() => handleFade('out')}
                      className="flex items-center gap-2 px-3 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                      title="Fade Out Selection"
                    >
                      <TrendingDown className="w-4 h-4" /> Fade Out
                    </button>
                    <div className="h-6 w-px bg-slate-700 mx-1" />
                    <button 
                      onClick={playRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-indigo-600/20 text-indigo-400 hover:bg-indigo-600/30 rounded-lg transition-all text-sm font-semibold border border-indigo-600/30"
                    >
                      <Play className="w-4 h-4" /> Listen
                    </button>
                    <button 
                      onClick={handleCut}
                      className="flex items-center gap-2 px-4 py-2 bg-rose-600/20 text-rose-400 hover:bg-rose-600/30 rounded-lg transition-all text-sm font-semibold border border-rose-600/30"
                    >
                      <Scissors className="w-4 h-4" /> Cut
                    </button>
                    <button 
                      onClick={clearRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-slate-600 rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <X className="w-4 h-4" /> Reset
                    </button>
                  </>
                ) : (
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={handleNormalize}
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <Activity className="w-4 h-4" /> Normalize
                    </button>
                    {audio.noiseProfile ? (
                       <button 
                        onClick={handleCleanAtmosphere}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white hover:bg-indigo-500 rounded-lg transition-all text-sm font-semibold border border-indigo-400 shadow-lg shadow-indigo-600/20 animate-pulse-subtle"
                      >
                        <Sparkles className="w-4 h-4" /> Clean Atmosphere
                      </button>
                    ) : (
                      <button 
                        onClick={handleDenoise}
                        className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                        title="Standard noise gate (select noise first for better results)"
                      >
                        <Wind className="w-4 h-4" /> Remove Noise
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="mt-8 text-center text-slate-600 text-[10px] uppercase tracking-[0.2em] flex flex-col gap-2">
        <span>Experimental Audio Node v1.7 • Spectral Profiler & Transition Fade Suite</span>
        <div className="flex justify-center gap-4 opacity-50">
          <span>{audio.isMono ? 'Mono' : 'Stereo'} Mode</span>
          <span>{formatTime(audio.duration)} Buffer</span>
        </div>
      </footer>

      <style>{`
        @keyframes pulse-subtle {
          0%, 100% { opacity: 1; transform: scale(1); }
          50% { opacity: 0.9; transform: scale(1.02); }
        }
        .animate-pulse-subtle {
          animation: pulse-subtle 2s infinite ease-in-out;
        }
      `}</style>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { 
  Play, 
  Pause, 
  Upload, 
  Scissors, 
  RotateCcw, 
  Volume2, 
  Maximize,
  FileAudio,
  Merge,
  Columns,
  Loader2,
  Download,
  X,
  Activity,
  Wind,
  Fingerprint,
  Sparkles,
  TrendingUp,
  TrendingDown,
  SkipBack,
  History
} from 'lucide-react';

// --- Audio Helpers ---

function writeString(view: DataView, offset: number, string: string) {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
}

function audioBufferToWav(buffer: AudioBuffer): Blob {
  const numChannels = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;
  const format = 1; // PCM
  const bitDepth = 16;
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numChannels * bytesPerSample;
  const bufferLength = buffer.length * blockAlign;
  const arrayBuffer = new ArrayBuffer(44 + bufferLength);
  const view = new DataView(arrayBuffer);

  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + bufferLength, true);
  writeString(view, 8, 'WAVE');
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, format, true);
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * blockAlign, true);
  view.setUint16(32, blockAlign, true);
  view.setUint16(34, bitDepth, true);
  writeString(view, 36, 'data');
  view.setUint32(40, bufferLength, true);

  let offset = 44;
  for (let i = 0; i < buffer.length; i++) {
    for (let channel = 0; channel < numChannels; channel++) {
      let sample = buffer.getChannelData(channel)[i];
      sample = Math.max(-1, Math.min(1, sample));
      sample = sample < 0 ? sample * 0x8000 : sample * 0x7FFF;
      view.setInt16(offset, sample, true);
      offset += 2;
    }
  }
  return new Blob([arrayBuffer], { type: 'audio/wav' });
}

// --- Types ---

interface AudioState {
  file: File | null;
  originalUrl: string | null;
  currentUrl: string | null;
  monoUrl: string | null;
  duration: number;
  currentTime: number;
  isPlaying: boolean;
  isReady: boolean;
  isMono: boolean;
  isProcessing: boolean;
  processingMsg: string;
  noiseProfile: Float32Array | null;
}

// --- App Component ---

const App: React.FC = () => {
  const [audio, setAudio] = useState<AudioState>({
    file: null,
    originalUrl: null,
    currentUrl: null,
    monoUrl: null,
    duration: 0,
    currentTime: 0,
    isPlaying: false,
    isReady: false,
    isMono: false,
    isProcessing: false,
    processingMsg: '',
    noiseProfile: null,
  });

  const [zoom, setZoom] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [activeRegion, setActiveRegion] = useState<any>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const wavesurferRef = useRef<WaveSurfer | null>(null);
  const regionsRef = useRef<any>(null);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !audio.currentUrl) return;

    const currentTime = wavesurferRef.current?.getCurrentTime() || 0;
    const wasPlaying = wavesurferRef.current?.isPlaying() || false;

    if (wavesurferRef.current) {
      wavesurferRef.current.destroy();
    }

    const ws = WaveSurfer.create({
      container: containerRef.current,
      waveColor: '#6366f1',
      progressColor: '#a5b4fc',
      cursorColor: '#f8fafc',
      barWidth: 2,
      barGap: 1,
      height: 256,
      normalize: true,
      splitChannels: !audio.isMono,
      url: audio.currentUrl,
      minPxPerSec: 50,
    });

    const regions = ws.registerPlugin(RegionsPlugin.create());
    regionsRef.current = regions;

    ws.on('ready', () => {
      setAudio(prev => ({ ...prev, duration: ws.getDuration(), isReady: true, isProcessing: false, processingMsg: '' }));
      ws.setTime(currentTime > ws.getDuration() ? 0 : currentTime);
      if (wasPlaying) ws.play();
    });

    ws.on('play', () => setAudio(prev => ({ ...prev, isPlaying: true })));
    ws.on('pause', () => setAudio(prev => ({ ...prev, isPlaying: false })));
    ws.on('timeupdate', (time) => setAudio(prev => ({ ...prev, currentTime: time })));

    regions.enableDragSelection({
      color: 'rgba(99, 102, 241, 0.2)',
    });

    regions.on('region-created', (region) => {
      regions.getRegions().forEach(r => {
        if (r !== region) r.remove();
      });
      setActiveRegion(region);
    });

    regions.on('region-updated', (region) => {
      setActiveRegion(region);
    });

    wavesurferRef.current = ws;

    return () => {
      ws.destroy();
    };
  }, [audio.currentUrl, audio.isMono]);

  const handleFileUpload = (file: File) => {
    if (file && file.type.startsWith('audio/')) {
      if (audio.originalUrl) URL.revokeObjectURL(audio.originalUrl);
      if (audio.monoUrl) URL.revokeObjectURL(audio.monoUrl);

      const url = URL.createObjectURL(file);
      setAudio({
        file,
        originalUrl: url,
        currentUrl: url,
        monoUrl: null,
        duration: 0,
        currentTime: 0,
        isPlaying: false,
        isReady: false,
        isMono: false,
        isProcessing: false,
        processingMsg: '',
        noiseProfile: null,
      });
      setActiveRegion(null);
    }
  };

  const handleRevert = () => {
    if (!audio.originalUrl || !confirm("Revert all edits to the original file?")) return;

    setAudio(prev => ({
      ...prev,
      currentUrl: prev.originalUrl,
      isMono: false,
      monoUrl: null,
      noiseProfile: null,
      isProcessing: false,
      processingMsg: ''
    }));
    setActiveRegion(null);
    regionsRef.current?.clearRegions();
  };

  const processAudio = async (msg: string, processor: (buffer: AudioBuffer) => AudioBuffer) => {
    if (!audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: msg }));

    try {
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const newBuffer = processor(sourceBuffer);
      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Processing failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleFade = (type: 'in' | 'out') => {
    if (!activeRegion || !audio.currentUrl) return;

    processAudio(`Applying Fade ${type === 'in' ? 'In' : 'Out'}...`, (buffer) => {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const sampleRate = buffer.sampleRate;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);
      const durationSamples = endOffset - startOffset;

      if (durationSamples <= 0) return buffer;

      for (let c = 0; c < buffer.numberOfChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < durationSamples; i++) {
          const index = startOffset + i;
          if (index >= data.length) break;

          let multiplier;
          if (type === 'in') {
            multiplier = i / durationSamples;
          } else {
            multiplier = 1 - (i / durationSamples);
          }
          data[index] *= multiplier;
        }
      }
      return buffer;
    });
  };

  const handleAnalyzeNoise = async () => {
    if (!activeRegion || !audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Analyzing noise fingerprint...' }));

    try {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const buffer = await audioCtx.decodeAudioData(arrayBuffer);

      const sampleRate = buffer.sampleRate;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);

      const data = buffer.getChannelData(0).subarray(startOffset, endOffset);
      const profileSize = 128;
      const profile = new Float32Array(profileSize);
      for (let i = 0; i < data.length; i++) {
        const bin = Math.floor((i % profileSize));
        profile[bin] += Math.abs(data[i]);
      }
      for (let i = 0; i < profileSize; i++) {
        profile[i] /= (data.length / profileSize);
      }

      setAudio(prev => ({
        ...prev,
        noiseProfile: profile,
        isProcessing: false,
        processingMsg: ''
      }));
      alert("Noise fingerprint captured. You can now use 'Clean Atmosphere'.");
    } catch (error) {
      console.error("Analysis failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleCleanAtmosphere = () => {
    if (!audio.noiseProfile) return;

    processAudio('Cleaning atmospheric noise...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      const profile = audio.noiseProfile!;
      const profileSize = profile.length;

      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          const bin = Math.floor((i % profileSize));
          const noiseEnergy = profile[bin];
          const sign = Math.sign(data[i]);
          let val = Math.abs(data[i]);

          if (val < noiseEnergy * 1.5) {
            val *= 0.1;
          } else {
            val -= noiseEnergy * 0.5;
          }
          data[i] = sign * Math.max(0, val);
        }
      }
      return buffer;
    });
  };

  const handleNormalize = () => {
    processAudio('Normalizing peaks...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      let maxVal = 0;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          const abs = Math.abs(data[i]);
          if (abs > maxVal) maxVal = abs;
        }
      }
      if (maxVal === 0) return buffer;
      const multiplier = 1.0 / maxVal;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          data[i] *= multiplier;
        }
      }
      return buffer;
    });
  };

  const handleDenoise = () => {
    processAudio('Removing silence noise...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      const threshold = 0.005;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          if (Math.abs(data[i]) < threshold) {
            data[i] = 0;
          }
        }
      }
      return buffer;
    });
  };

  const handleCut = async () => {
    if (!activeRegion || !audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Cutting selection...' }));

    try {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const sampleRate = sourceBuffer.sampleRate;
      const numChannels = sourceBuffer.numberOfChannels;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);
      const cutSamples = endOffset - startOffset;
      const newLength = sourceBuffer.length - cutSamples;

      if (newLength <= 0) {
        alert("Empty result aborted.");
        setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
        return;
      }

      const newBuffer = audioCtx.createBuffer(numChannels, newLength, sampleRate);
      for (let channel = 0; channel < numChannels; channel++) {
        const oldData = sourceBuffer.getChannelData(channel);
        const newData = newBuffer.getChannelData(channel);
        newData.set(oldData.subarray(0, startOffset));
        newData.set(oldData.subarray(endOffset), startOffset);
      }

      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Cut failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const toggleMono = async () => {
    if (!audio.originalUrl) return;
    if (!audio.isMono) {
      setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Mixing to Mono...' }));
      try {
        const response = await fetch(audio.currentUrl || audio.originalUrl);
        const arrayBuffer = await response.arrayBuffer();
        const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);
        const offlineCtx = new OfflineAudioContext(1, audioBuffer.length, audioBuffer.sampleRate);
        const source = offlineCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(offlineCtx.destination);
        source.start();
        const monoBuffer = await offlineCtx.startRendering();
        const monoBlob = audioBufferToWav(monoBuffer);
        const monoUrl = URL.createObjectURL(monoBlob);
        setAudio(prev => ({ ...prev, isMono: true, currentUrl: monoUrl, monoUrl: monoUrl, isProcessing: false }));
      } catch (e) { setAudio(prev => ({ ...prev, isProcessing: false })); }
    } else {
      setAudio(prev => ({ ...prev, isMono: false, currentUrl: prev.originalUrl }));
    }
  };

  const handleDownload = () => {
    if (!audio.currentUrl) return;
    const link = document.createElement('a');
    link.href = audio.currentUrl;
    const originalName = audio.file?.name || 'audio';
    const nameWithoutExt = originalName.substring(0, originalName.lastIndexOf('.')) || originalName;
    link.download = `${nameWithoutExt}-edited.wav`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    handleFileUpload(file);
  }, []);

  const togglePlay = () => wavesurferRef.current?.playPause();
  const playRegion = () => activeRegion?.play();
  const seekToStart = () => wavesurferRef.current?.setTime(0);
  const clearRegion = () => {
    regionsRef.current?.clearRegions();
    setActiveRegion(null);
  };

  const handleZoom = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(e.target.value);
    setZoom(value);
    wavesurferRef.current?.zoom(value);
  };

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div 
      className={`min-h-screen flex flex-col p-6 transition-colors duration-300 ${isDragging ? 'bg-indigo-950/20' : 'bg-slate-900'}`}
      onDrop={onDrop}
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
    >
      <header className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg shadow-lg shadow-indigo-600/20">
            <Volume2 className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-white">AudioWave <span className="text-indigo-400">Editor</span></h1>
        </div>

        <div className="flex items-center gap-3">
          {audio.currentUrl && (
            <>
              <button 
                onClick={handleRevert}
                className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-rose-400 px-4 py-2 rounded-full transition-all border border-slate-700"
                title="Reset to original file"
              >
                <RotateCcw className="w-4 h-4" />
                <span className="text-sm font-medium">Reset All</span>
              </button>
              <button 
                onClick={handleDownload}
                className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded-full transition-all shadow-lg shadow-emerald-600/20 border border-emerald-500/50"
              >
                <Download className="w-4 h-4" />
                <span className="text-sm font-medium">Save As</span>
              </button>
            </>
          )}
          <label className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-full cursor-pointer transition-all border border-indigo-500 shadow-lg shadow-indigo-600/20">
            <Upload className="w-4 h-4" />
            <span className="text-sm font-medium">Upload File</span>
            <input type="file" className="hidden" accept="audio/*" onChange={(e) => e.target.files && handleFileUpload(e.target.files[0])} />
          </label>
        </div>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center">
        {!audio.currentUrl ? (
          <div className="text-center p-12 border-2 border-dashed border-slate-700 rounded-3xl max-w-lg w-full bg-slate-800/50 backdrop-blur-sm">
            <FileAudio className="w-16 h-16 text-slate-600 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-slate-300 mb-2">No audio loaded</h2>
            <p className="text-slate-500 mb-6 text-sm">Drag and drop audio here to begin multi-channel editing and processing.</p>
          </div>
        ) : (
          <div className="w-full max-w-6xl space-y-6">
            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-2xl relative overflow-hidden">
              {audio.isProcessing && (
                <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center">
                  <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                  <p className="text-white font-medium">{audio.processingMsg}</p>
                </div>
              )}

              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-500/20 p-1.5 rounded-md border border-indigo-500/30">
                    <History className="w-4 h-4 text-indigo-400" />
                  </div>
                  <div>
                    <h3 className="text-indigo-400 font-medium text-[10px] uppercase tracking-widest">Active Project</h3>
                    <p className="text-white font-semibold truncate max-w-md">{audio.file?.name}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-slate-400 text-sm font-mono">{formatTime(audio.currentTime)} / {formatTime(audio.duration)}</p>
                </div>
              </div>

              <div className="relative">
                {!audio.isMono && (
                  <>
                    <div className="absolute top-2 left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL L
                    </div>
                    <div className="absolute top-[134px] left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL R
                    </div>
                  </>
                )}
                {audio.isMono && (
                  <div className="absolute top-2 left-2 z-10 bg-emerald-500/20 text-emerald-400 backdrop-blur-md border border-emerald-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                    MONO MASTER MIX
                  </div>
                )}
                <div ref={containerRef} className="waveform-container rounded-lg bg-slate-900/50 p-2 border border-slate-700/50" />
              </div>
            </div>

            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-4 flex flex-wrap items-center justify-between gap-6 shadow-xl">
              <div className="flex items-center gap-3">
                <button 
                  onClick={seekToStart} 
                  title="Back to Beginning"
                  className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-700 hover:bg-slate-600 text-slate-200 border border-slate-600 transition-all"
                >
                  <SkipBack className="w-5 h-5" />
                </button>
                <button 
                  onClick={togglePlay} 
                  disabled={!audio.isReady || audio.isProcessing}
                  className="w-12 h-12 flex items-center justify-center rounded-full bg-indigo-600 hover:bg-indigo-500 text-white transition-all shadow-lg shadow-indigo-600/20 disabled:opacity-50"
                >
                  {audio.isPlaying ? <Pause /> : <Play className="ml-1" />}
                </button>
                <div className="h-8 w-px bg-slate-700 mx-2" />
                <button 
                  onClick={toggleMono}
                  disabled={audio.isProcessing}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all text-sm font-semibold border ${
                    audio.isMono 
                    ? 'bg-emerald-600 text-white border-emerald-400 shadow-lg shadow-emerald-600/20' 
                    : 'bg-slate-700 text-slate-300 border-slate-600 hover:bg-slate-600'
                  }`}
                >
                  {audio.isProcessing && audio.processingMsg.includes('Mono') ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : audio.isMono ? (
                    <Columns className="w-4 h-4" />
                  ) : (
                    <Merge className="w-4 h-4" />
                  )}
                  {audio.isMono ? 'Stereo' : 'Mix Mono'}
                </button>
              </div>

              <div className="flex items-center gap-4 flex-1 max-w-[200px]">
                <Maximize className="w-4 h-4 text-slate-500" />
                <input type="range" min="0" max="500" value={zoom} onChange={handleZoom} className="flex-1 accent-indigo-500 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
              </div>

              <div className="flex items-center gap-3 border-l border-slate-700 pl-6">
                {activeRegion ? (
                  <>
                    <button 
                      onClick={handleAnalyzeNoise}
                      className="flex items-center gap-2 px-4 py-2 bg-amber-600/20 text-amber-400 hover:bg-amber-600/30 rounded-lg transition-all text-sm font-semibold border border-amber-600/30"
                      title="Learn background atmosphere from this selection"
                    >
                      <Fingerprint className="w-4 h-4" /> Analyze Noise
                    </button>
                    <div className="h-6 w-px bg-slate-700 mx-1" />
                    <button 
                      onClick={() => handleFade('in')}
                      className="flex items-center gap-2 px-3 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                      title="Fade In Selection"
                    >
                      <TrendingUp className="w-4 h-4" /> Fade In
                    </button>
                    <button 
                      onClick={() => handleFade('out')}
                      className="flex items-center gap-2 px-3 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                      title="Fade Out Selection"
                    >
                      <TrendingDown className="w-4 h-4" /> Fade Out
                    </button>
                    <div className="h-6 w-px bg-slate-700 mx-1" />
                    <button 
                      onClick={playRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-indigo-600/20 text-indigo-400 hover:bg-indigo-600/30 rounded-lg transition-all text-sm font-semibold border border-indigo-600/30"
                    >
                      <Play className="w-4 h-4" /> Listen
                    </button>
                    <button 
                      onClick={handleCut}
                      className="flex items-center gap-2 px-4 py-2 bg-rose-600/20 text-rose-400 hover:bg-rose-600/30 rounded-lg transition-all text-sm font-semibold border border-rose-600/30"
                    >
                      <Scissors className="w-4 h-4" /> Cut
                    </button>
                    <button 
                      onClick={clearRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-slate-600 rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <X className="w-4 h-4" /> Reset
                    </button>
                  </>
                ) : (
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={handleNormalize}
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <Activity className="w-4 h-4" /> Normalize
                    </button>
                    {audio.noiseProfile ? (
                       <button 
                        onClick={handleCleanAtmosphere}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white hover:bg-indigo-500 rounded-lg transition-all text-sm font-semibold border border-indigo-400 shadow-lg shadow-indigo-600/20 animate-pulse-subtle"
                      >
                        <Sparkles className="w-4 h-4" /> Clean Atmosphere
                      </button>
                    ) : (
                      <button 
                        onClick={handleDenoise}
                        className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                        title="Standard noise gate (select noise first for better results)"
                      >
                        <Wind className="w-4 h-4" /> Remove Noise
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="mt-8 text-center text-slate-600 text-[10px] uppercase tracking-[0.2em] flex flex-col gap-2">
        <span>Experimental Audio Node v1.8 • Multi-Channel Suite & Revert History</span>
        <div className="flex justify-center gap-4 opacity-50">
          <span>{audio.isMono ? 'Mono' : 'Stereo'} Mode</span>
          <span>{formatTime(audio.duration)} Buffer</span>
        </div>
      </footer>

      <style>{`
        @keyframes pulse-subtle {
          0%, 100% { opacity: 1; transform: scale(1); }
          50% { opacity: 0.9; transform: scale(1.02); }
        }
        .animate-pulse-subtle {
          animation: pulse-subtle 2s infinite ease-in-out;
        }
      `}</style>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { 
  Play, 
  Pause, 
  Upload, 
  Scissors, 
  RotateCcw, 
  Volume2, 
  Maximize,
  FileAudio,
  Merge,
  Columns,
  Loader2,
  Download,
  X,
  Activity,
  Wind,
  Fingerprint,
  Sparkles,
  TrendingUp,
  TrendingDown,
  SkipBack,
  History
} from 'lucide-react';

// --- Audio Helpers ---

function writeString(view: DataView, offset: number, string: string) {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
}

function audioBufferToWav(buffer: AudioBuffer): Blob {
  const numChannels = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;
  const format = 1; // PCM
  const bitDepth = 16;
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numChannels * bytesPerSample;
  const bufferLength = buffer.length * blockAlign;
  const arrayBuffer = new ArrayBuffer(44 + bufferLength);
  const view = new DataView(arrayBuffer);

  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + bufferLength, true);
  writeString(view, 8, 'WAVE');
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, format, true);
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * blockAlign, true);
  view.setUint16(32, blockAlign, true);
  view.setUint16(34, bitDepth, true);
  writeString(view, 36, 'data');
  view.setUint32(40, bufferLength, true);

  let offset = 44;
  for (let i = 0; i < buffer.length; i++) {
    for (let channel = 0; channel < numChannels; channel++) {
      let sample = buffer.getChannelData(channel)[i];
      sample = Math.max(-1, Math.min(1, sample));
      sample = sample < 0 ? sample * 0x8000 : sample * 0x7FFF;
      view.setInt16(offset, sample, true);
      offset += 2;
    }
  }
  return new Blob([arrayBuffer], { type: 'audio/wav' });
}

// --- Types ---

interface AudioState {
  file: File | null;
  originalUrl: string | null;
  currentUrl: string | null;
  monoUrl: string | null;
  duration: number;
  currentTime: number;
  isPlaying: boolean;
  isReady: boolean;
  isMono: boolean;
  isProcessing: boolean;
  processingMsg: string;
  noiseProfile: Float32Array | null;
}

// --- App Component ---

const App: React.FC = () => {
  const [audio, setAudio] = useState<AudioState>({
    file: null,
    originalUrl: null,
    currentUrl: null,
    monoUrl: null,
    duration: 0,
    currentTime: 0,
    isPlaying: false,
    isReady: false,
    isMono: false,
    isProcessing: false,
    processingMsg: '',
    noiseProfile: null,
  });

  const [zoom, setZoom] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [activeRegion, setActiveRegion] = useState<any>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const wavesurferRef = useRef<WaveSurfer | null>(null);
  const regionsRef = useRef<any>(null);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !audio.currentUrl) return;

    const currentTime = wavesurferRef.current?.getCurrentTime() || 0;
    const wasPlaying = wavesurferRef.current?.isPlaying() || false;

    if (wavesurferRef.current) {
      wavesurferRef.current.destroy();
    }

    const ws = WaveSurfer.create({
      container: containerRef.current,
      waveColor: '#6366f1',
      progressColor: '#a5b4fc',
      cursorColor: '#f8fafc',
      barWidth: 2,
      barGap: 1,
      height: 256,
      normalize: true,
      // Fix: In some WaveSurfer v7 types, splitChannels is strictly defined as an array.
      // We use 'as any' here because WaveSurfer's runtime implementation correctly handles boolean.
      splitChannels: (!audio.isMono) as any,
      url: audio.currentUrl,
      minPxPerSec: 50,
    });

    const regions = ws.registerPlugin(RegionsPlugin.create());
    regionsRef.current = regions;

    ws.on('ready', () => {
      setAudio(prev => ({ ...prev, duration: ws.getDuration(), isReady: true, isProcessing: false, processingMsg: '' }));
      ws.setTime(currentTime > ws.getDuration() ? 0 : currentTime);
      if (wasPlaying) ws.play();
    });

    ws.on('play', () => setAudio(prev => ({ ...prev, isPlaying: true })));
    ws.on('pause', () => setAudio(prev => ({ ...prev, isPlaying: false })));
    ws.on('timeupdate', (time) => setAudio(prev => ({ ...prev, currentTime: time })));

    regions.enableDragSelection({
      color: 'rgba(99, 102, 241, 0.2)',
    });

    regions.on('region-created', (region) => {
      regions.getRegions().forEach(r => {
        if (r !== region) r.remove();
      });
      setActiveRegion(region);
    });

    regions.on('region-updated', (region) => {
      setActiveRegion(region);
    });

    wavesurferRef.current = ws;

    return () => {
      ws.destroy();
    };
  }, [audio.currentUrl, audio.isMono]);

  const handleFileUpload = (file: File) => {
    if (file && file.type.startsWith('audio/')) {
      if (audio.originalUrl) URL.revokeObjectURL(audio.originalUrl);
      if (audio.monoUrl) URL.revokeObjectURL(audio.monoUrl);

      const url = URL.createObjectURL(file);
      setAudio({
        file,
        originalUrl: url,
        currentUrl: url,
        monoUrl: null,
        duration: 0,
        currentTime: 0,
        isPlaying: false,
        isReady: false,
        isMono: false,
        isProcessing: false,
        processingMsg: '',
        noiseProfile: null,
      });
      setActiveRegion(null);
    }
  };

  const handleRevert = () => {
    if (!audio.originalUrl || !confirm("Revert all edits to the original file?")) return;

    setAudio(prev => ({
      ...prev,
      currentUrl: prev.originalUrl,
      isMono: false,
      monoUrl: null,
      noiseProfile: null,
      isProcessing: false,
      processingMsg: ''
    }));
    setActiveRegion(null);
    regionsRef.current?.clearRegions();
  };

  const processAudio = async (msg: string, processor: (buffer: AudioBuffer) => AudioBuffer) => {
    if (!audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: msg }));

    try {
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const newBuffer = processor(sourceBuffer);
      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Processing failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleFade = (type: 'in' | 'out') => {
    if (!activeRegion || !audio.currentUrl) return;

    processAudio(`Applying Fade ${type === 'in' ? 'In' : 'Out'}...`, (buffer) => {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const sampleRate = buffer.sampleRate;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);
      const durationSamples = endOffset - startOffset;

      if (durationSamples <= 0) return buffer;

      for (let c = 0; c < buffer.numberOfChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < durationSamples; i++) {
          const index = startOffset + i;
          if (index >= data.length) break;

          let multiplier;
          if (type === 'in') {
            multiplier = i / durationSamples;
          } else {
            multiplier = 1 - (i / durationSamples);
          }
          data[index] *= multiplier;
        }
      }
      return buffer;
    });
  };

  const handleAnalyzeNoise = async () => {
    if (!activeRegion || !audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Analyzing noise fingerprint...' }));

    try {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const buffer = await audioCtx.decodeAudioData(arrayBuffer);

      const sampleRate = buffer.sampleRate;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);

      const data = buffer.getChannelData(0).subarray(startOffset, endOffset);
      const profileSize = 128;
      const profile = new Float32Array(profileSize);
      for (let i = 0; i < data.length; i++) {
        const bin = Math.floor((i % profileSize));
        profile[bin] += Math.abs(data[i]);
      }
      for (let i = 0; i < profileSize; i++) {
        profile[i] /= (data.length / profileSize);
      }

      setAudio(prev => ({
        ...prev,
        noiseProfile: profile,
        isProcessing: false,
        processingMsg: ''
      }));
      alert("Noise fingerprint captured. You can now use 'Clean Atmosphere'.");
    } catch (error) {
      console.error("Analysis failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleCleanAtmosphere = () => {
    if (!audio.noiseProfile) return;

    processAudio('Cleaning atmospheric noise...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      const profile = audio.noiseProfile!;
      const profileSize = profile.length;

      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          const bin = Math.floor((i % profileSize));
          const noiseEnergy = profile[bin];
          const sign = Math.sign(data[i]);
          let val = Math.abs(data[i]);

          if (val < noiseEnergy * 1.5) {
            val *= 0.1;
          } else {
            val -= noiseEnergy * 0.5;
          }
          data[i] = sign * Math.max(0, val);
        }
      }
      return buffer;
    });
  };

  const handleNormalize = () => {
    processAudio('Normalizing peaks...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      let maxVal = 0;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          const abs = Math.abs(data[i]);
          if (abs > maxVal) maxVal = abs;
        }
      }
      if (maxVal === 0) return buffer;
      const multiplier = 1.0 / maxVal;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          data[i] *= multiplier;
        }
      }
      return buffer;
    });
  };

  const handleDenoise = () => {
    processAudio('Removing silence noise...', (buffer) => {
      const numChannels = buffer.numberOfChannels;
      const threshold = 0.005;
      for (let c = 0; c < numChannels; c++) {
        const data = buffer.getChannelData(c);
        for (let i = 0; i < data.length; i++) {
          if (Math.abs(data[i]) < threshold) {
            data[i] = 0;
          }
        }
      }
      return buffer;
    });
  };

  const handleCut = async () => {
    if (!activeRegion || !audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Cutting selection...' }));

    try {
      const start = activeRegion.start;
      const end = activeRegion.end;
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const sampleRate = sourceBuffer.sampleRate;
      const numChannels = sourceBuffer.numberOfChannels;
      const startOffset = Math.floor(start * sampleRate);
      const endOffset = Math.floor(end * sampleRate);
      const cutSamples = endOffset - startOffset;
      const newLength = sourceBuffer.length - cutSamples;

      if (newLength <= 0) {
        alert("Empty result aborted.");
        setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
        return;
      }

      const newBuffer = audioCtx.createBuffer(numChannels, newLength, sampleRate);
      for (let channel = 0; channel < numChannels; channel++) {
        const oldData = sourceBuffer.getChannelData(channel);
        const newData = newBuffer.getChannelData(channel);
        newData.set(oldData.subarray(0, startOffset));
        newData.set(oldData.subarray(endOffset), startOffset);
      }

      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Cut failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const toggleMono = async () => {
    if (!audio.originalUrl) return;
    if (!audio.isMono) {
      setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Mixing to Mono...' }));
      try {
        const response = await fetch(audio.currentUrl || audio.originalUrl);
        const arrayBuffer = await response.arrayBuffer();
        const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
        const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);
        const offlineCtx = new OfflineAudioContext(1, audioBuffer.length, audioBuffer.sampleRate);
        const source = offlineCtx.createBufferSource();
        source.buffer = audioBuffer;
        source.connect(offlineCtx.destination);
        source.start();
        const monoBuffer = await offlineCtx.startRendering();
        const monoBlob = audioBufferToWav(monoBuffer);
        const monoUrl = URL.createObjectURL(monoBlob);
        setAudio(prev => ({ ...prev, isMono: true, currentUrl: monoUrl, monoUrl: monoUrl, isProcessing: false }));
      } catch (e) { setAudio(prev => ({ ...prev, isProcessing: false })); }
    } else {
      setAudio(prev => ({ ...prev, isMono: false, currentUrl: prev.originalUrl }));
    }
  };

  const handleDownload = () => {
    if (!audio.currentUrl) return;
    const link = document.createElement('a');
    link.href = audio.currentUrl;
    const originalName = audio.file?.name || 'audio';
    const nameWithoutExt = originalName.substring(0, originalName.lastIndexOf('.')) || originalName;
    link.download = `${nameWithoutExt}-edited.wav`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    handleFileUpload(file);
  }, []);

  const togglePlay = () => wavesurferRef.current?.playPause();
  const playRegion = () => activeRegion?.play();
  const seekToStart = () => wavesurferRef.current?.setTime(0);
  const clearRegion = () => {
    regionsRef.current?.clearRegions();
    setActiveRegion(null);
  };

  const handleZoom = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(e.target.value);
    setZoom(value);
    wavesurferRef.current?.zoom(value);
  };

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div 
      className={`min-h-screen flex flex-col p-6 transition-colors duration-300 ${isDragging ? 'bg-indigo-950/20' : 'bg-slate-900'}`}
      onDrop={onDrop}
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
    >
      <header className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg shadow-lg shadow-indigo-600/20">
            <Volume2 className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-white">AudioWave <span className="text-indigo-400">Editor</span></h1>
        </div>

        <div className="flex items-center gap-3">
          {audio.currentUrl && (
            <>
              <button 
                onClick={handleRevert}
                className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-rose-400 px-4 py-2 rounded-full transition-all border border-slate-700"
                title="Reset to original file"
              >
                <RotateCcw className="w-4 h-4" />
                <span className="text-sm font-medium">Reset All</span>
              </button>
              <button 
                onClick={handleDownload}
                className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded-full transition-all shadow-lg shadow-emerald-600/20 border border-emerald-500/50"
              >
                <Download className="w-4 h-4" />
                <span className="text-sm font-medium">Save As</span>
              </button>
            </>
          )}
          <label className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-full cursor-pointer transition-all border border-indigo-500 shadow-lg shadow-indigo-600/20">
            <Upload className="w-4 h-4" />
            <span className="text-sm font-medium">Upload File</span>
            <input type="file" className="hidden" accept="audio/*" onChange={(e) => e.target.files && handleFileUpload(e.target.files[0])} />
          </label>
        </div>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center">
        {!audio.currentUrl ? (
          <div className="text-center p-12 border-2 border-dashed border-slate-700 rounded-3xl max-w-lg w-full bg-slate-800/50 backdrop-blur-sm">
            <FileAudio className="w-16 h-16 text-slate-600 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-slate-300 mb-2">No audio loaded</h2>
            <p className="text-slate-500 mb-6 text-sm">Drag and drop audio here to begin multi-channel editing and processing.</p>
          </div>
        ) : (
          <div className="w-full max-w-6xl space-y-6">
            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-2xl relative overflow-hidden">
              {audio.isProcessing && (
                <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center">
                  <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                  <p className="text-white font-medium">{audio.processingMsg}</p>
                </div>
              )}

              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-500/20 p-1.5 rounded-md border border-indigo-500/30">
                    <History className="w-4 h-4 text-indigo-400" />
                  </div>
                  <div>
                    <h3 className="text-indigo-400 font-medium text-[10px] uppercase tracking-widest">Active Project</h3>
                    <p className="text-white font-semibold truncate max-w-md">{audio.file?.name}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-slate-400 text-sm font-mono">{formatTime(audio.currentTime)} / {formatTime(audio.duration)}</p>
                </div>
              </div>

              <div className="relative">
                {!audio.isMono && (
                  <>
                    <div className="absolute top-2 left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL L
                    </div>
                    <div className="absolute top-[134px] left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL R
                    </div>
                  </>
                )}
                {audio.isMono && (
                  <div className="absolute top-2 left-2 z-10 bg-emerald-500/20 text-emerald-400 backdrop-blur-md border border-emerald-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                    MONO MASTER MIX
                  </div>
                )}
                <div ref={containerRef} className="waveform-container rounded-lg bg-slate-900/50 p-2 border border-slate-700/50" />
              </div>
            </div>

            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-4 flex flex-wrap items-center justify-between gap-6 shadow-xl">
              <div className="flex items-center gap-3">
                <button 
                  onClick={seekToStart} 
                  title="Back to Beginning"
                  className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-700 hover:bg-slate-600 text-slate-200 border border-slate-600 transition-all"
                >
                  <SkipBack className="w-5 h-5" />
                </button>
                <button 
                  onClick={togglePlay} 
                  disabled={!audio.isReady || audio.isProcessing}
                  className="w-12 h-12 flex items-center justify-center rounded-full bg-indigo-600 hover:bg-indigo-500 text-white transition-all shadow-lg shadow-indigo-600/20 disabled:opacity-50"
                >
                  {audio.isPlaying ? <Pause /> : <Play className="ml-1" />}
                </button>
                <div className="h-8 w-px bg-slate-700 mx-2" />
                <button 
                  onClick={toggleMono}
                  disabled={audio.isProcessing}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all text-sm font-semibold border ${
                    audio.isMono 
                    ? 'bg-emerald-600 text-white border-emerald-400 shadow-lg shadow-emerald-600/20' 
                    : 'bg-slate-700 text-slate-300 border-slate-600 hover:bg-slate-600'
                  }`}
                >
                  {audio.isProcessing && audio.processingMsg.includes('Mono') ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : audio.isMono ? (
                    <Columns className="w-4 h-4" />
                  ) : (
                    <Merge className="w-4 h-4" />
                  )}
                  {audio.isMono ? 'Stereo' : 'Mix Mono'}
                </button>
              </div>

              <div className="flex items-center gap-4 flex-1 max-w-[200px]">
                <Maximize className="w-4 h-4 text-slate-500" />
                <input type="range" min="0" max="500" value={zoom} onChange={handleZoom} className="flex-1 accent-indigo-500 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
              </div>

              <div className="flex items-center gap-3 border-l border-slate-700 pl-6">
                {activeRegion ? (
                  <>
                    <button 
                      onClick={handleAnalyzeNoise}
                      className="flex items-center gap-2 px-4 py-2 bg-amber-600/20 text-amber-400 hover:bg-amber-600/30 rounded-lg transition-all text-sm font-semibold border border-amber-600/30"
                      title="Learn background atmosphere from this selection"
                    >
                      <Fingerprint className="w-4 h-4" /> Analyze Noise
                    </button>
                    <div className="h-6 w-px bg-slate-700 mx-1" />
                    <button 
                      onClick={() => handleFade('in')}
                      className="flex items-center gap-2 px-3 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                      title="Fade In Selection"
                    >
                      <TrendingUp className="w-4 h-4" /> Fade In
                    </button>
                    <button 
                      onClick={() => handleFade('out')}
                      className="flex items-center gap-2 px-3 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                      title="Fade Out Selection"
                    >
                      <TrendingDown className="w-4 h-4" /> Fade Out
                    </button>
                    <div className="h-6 w-px bg-slate-700 mx-1" />
                    <button 
                      onClick={playRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-indigo-600/20 text-indigo-400 hover:bg-indigo-600/30 rounded-lg transition-all text-sm font-semibold border border-indigo-600/30"
                    >
                      <Play className="w-4 h-4" /> Listen
                    </button>
                    <button 
                      onClick={handleCut}
                      className="flex items-center gap-2 px-4 py-2 bg-rose-600/20 text-rose-400 hover:bg-rose-600/30 rounded-lg transition-all text-sm font-semibold border border-rose-600/30"
                    >
                      <Scissors className="w-4 h-4" /> Cut
                    </button>
                    <button 
                      onClick={clearRegion} 
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-slate-600 rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <X className="w-4 h-4" /> Reset
                    </button>
                  </>
                ) : (
                  <div className="flex items-center gap-2">
                    <button 
                      onClick={handleNormalize}
                      className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                    >
                      <Activity className="w-4 h-4" /> Normalize
                    </button>
                    {audio.noiseProfile ? (
                       <button 
                        onClick={handleCleanAtmosphere}
                        className="flex items-center gap-2 px-4 py-2 bg-indigo-600 text-white hover:bg-indigo-500 rounded-lg transition-all text-sm font-semibold border border-indigo-400 shadow-lg shadow-indigo-600/20 animate-pulse-subtle"
                      >
                        <Sparkles className="w-4 h-4" /> Clean Atmosphere
                      </button>
                    ) : (
                      <button 
                        onClick={handleDenoise}
                        className="flex items-center gap-2 px-4 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                        title="Standard noise gate (select noise first for better results)"
                      >
                        <Wind className="w-4 h-4" /> Remove Noise
                      </button>
                    )}
                  </div>
                )}
              </div>
            </div>
          </div>
        )}
      </main>

      <footer className="mt-8 text-center text-slate-600 text-[10px] uppercase tracking-[0.2em] flex flex-col gap-2">
        <span>Experimental Audio Node v1.8 • Multi-Channel Suite & Revert History</span>
        <div className="flex justify-center gap-4 opacity-50">
          <span>{audio.isMono ? 'Mono' : 'Stereo'} Mode</span>
          <span>{formatTime(audio.duration)} Buffer</span>
        </div>
      </footer>

      <style>{`
        @keyframes pulse-subtle {
          0%, 100% { opacity: 1; transform: scale(1); }
          50% { opacity: 0.9; transform: scale(1.02); }
        }
        .animate-pulse-subtle {
          animation: pulse-subtle 2s infinite ease-in-out;
        }
      `}</style>
    </div>
  );
};

const root = createRoot(document.getElementById('root')!);
root.render(<App />);

/**
 * Business logic for audio processing, WAV encoding, and buffer manipulation.
 */

export function writeString(view: DataView, offset: number, string: string) {
  for (let i = 0; i < string.length; i++) {
    view.setUint8(offset + i, string.charCodeAt(i));
  }
}

export function audioBufferToWav(buffer: AudioBuffer): Blob {
  const numChannels = buffer.numberOfChannels;
  const sampleRate = buffer.sampleRate;
  const format = 1; // PCM
  const bitDepth = 16;
  const bytesPerSample = bitDepth / 8;
  const blockAlign = numChannels * bytesPerSample;
  const bufferLength = buffer.length * blockAlign;
  const arrayBuffer = new ArrayBuffer(44 + bufferLength);
  const view = new DataView(arrayBuffer);

  writeString(view, 0, 'RIFF');
  view.setUint32(4, 36 + bufferLength, true);
  writeString(view, 8, 'WAVE');
  writeString(view, 12, 'fmt ');
  view.setUint32(16, 16, true);
  view.setUint16(20, format, true);
  view.setUint16(22, numChannels, true);
  view.setUint32(24, sampleRate, true);
  view.setUint32(28, sampleRate * blockAlign, true);
  view.setUint16(32, blockAlign, true);
  view.setUint16(34, bitDepth, true);
  writeString(view, 36, 'data');
  view.setUint32(40, bufferLength, true);

  let offset = 44;
  for (let i = 0; i < buffer.length; i++) {
    for (let channel = 0; channel < numChannels; channel++) {
      let sample = buffer.getChannelData(channel)[i];
      sample = Math.max(-1, Math.min(1, sample));
      sample = sample < 0 ? sample * 0x8000 : sample * 0x7FFF;
      view.setInt16(offset, sample, true);
      offset += 2;
    }
  }
  return new Blob([arrayBuffer], { type: 'audio/wav' });
}

export function applyFade(buffer: AudioBuffer, start: number, end: number, type: 'in' | 'out'): AudioBuffer {
  const sampleRate = buffer.sampleRate;
  const startOffset = Math.floor(start * sampleRate);
  const endOffset = Math.floor(end * sampleRate);
  const durationSamples = endOffset - startOffset;

  if (durationSamples <= 0) return buffer;

  for (let c = 0; c < buffer.numberOfChannels; c++) {
    const data = buffer.getChannelData(c);
    for (let i = 0; i < durationSamples; i++) {
      const index = startOffset + i;
      if (index >= data.length) break;

      let multiplier = type === 'in' ? i / durationSamples : 1 - (i / durationSamples);
      data[index] *= multiplier;
    }
  }
  return buffer;
}

export function analyzeNoiseProfile(buffer: AudioBuffer, start: number, end: number): Float32Array {
  const sampleRate = buffer.sampleRate;
  const startOffset = Math.floor(start * sampleRate);
  const endOffset = Math.floor(end * sampleRate);

  const data = buffer.getChannelData(0).subarray(startOffset, endOffset);
  const profileSize = 128;
  const profile = new Float32Array(profileSize);

  for (let i = 0; i < data.length; i++) {
    const bin = Math.floor((i % profileSize));
    profile[bin] += Math.abs(data[i]);
  }
  for (let i = 0; i < profileSize; i++) {
    profile[i] /= (data.length / profileSize);
  }
  return profile;
}

export function applySpectralSubtraction(buffer: AudioBuffer, profile: Float32Array): AudioBuffer {
  const numChannels = buffer.numberOfChannels;
  const profileSize = profile.length;

  for (let c = 0; c < numChannels; c++) {
    const data = buffer.getChannelData(c);
    for (let i = 0; i < data.length; i++) {
      const bin = Math.floor((i % profileSize));
      const noiseEnergy = profile[bin];
      const sign = Math.sign(data[i]);
      let val = Math.abs(data[i]);

      if (val < noiseEnergy * 1.5) {
        val *= 0.1;
      } else {
        val -= noiseEnergy * 0.5;
      }
      data[i] = sign * Math.max(0, val);
    }
  }
  return buffer;
}

export function applyNormalization(buffer: AudioBuffer): AudioBuffer {
  const numChannels = buffer.numberOfChannels;
  let maxVal = 0;
  for (let c = 0; c < numChannels; c++) {
    const data = buffer.getChannelData(c);
    for (let i = 0; i < data.length; i++) {
      const abs = Math.abs(data[i]);
      if (abs > maxVal) maxVal = abs;
    }
  }
  if (maxVal === 0) return buffer;
  const multiplier = 1.0 / maxVal;
  for (let c = 0; c < numChannels; c++) {
    const data = buffer.getChannelData(c);
    for (let i = 0; i < data.length; i++) {
      data[i] *= multiplier;
    }
  }
  return buffer;
}

export function applyNoiseGate(buffer: AudioBuffer, threshold = 0.005): AudioBuffer {
  const numChannels = buffer.numberOfChannels;
  for (let c = 0; c < numChannels; c++) {
    const data = buffer.getChannelData(c);
    for (let i = 0; i < data.length; i++) {
      if (Math.abs(data[i]) < threshold) {
        data[i] = 0;
      }
    }
  }
  return buffer;
}

export function applyCut(buffer: AudioBuffer, start: number, end: number, audioCtx: AudioContext): AudioBuffer | null {
  const sampleRate = buffer.sampleRate;
  const numChannels = buffer.numberOfChannels;
  const startOffset = Math.floor(start * sampleRate);
  const endOffset = Math.floor(end * sampleRate);
  const cutSamples = endOffset - startOffset;
  const newLength = buffer.length - cutSamples;

  if (newLength <= 0) return null;

  const newBuffer = audioCtx.createBuffer(numChannels, newLength, sampleRate);
  for (let channel = 0; channel < numChannels; channel++) {
    const oldData = buffer.getChannelData(channel);
    const newData = newBuffer.getChannelData(channel);
    newData.set(oldData.subarray(0, startOffset));
    newData.set(oldData.subarray(endOffset), startOffset);
  }
  return newBuffer;
}

export async function mixToMono(originalUrl: string): Promise<Blob> {
  const response = await fetch(originalUrl);
  const arrayBuffer = await response.arrayBuffer();
  const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
  const audioBuffer = await audioCtx.decodeAudioData(arrayBuffer);
  const offlineCtx = new OfflineAudioContext(1, audioBuffer.length, audioBuffer.sampleRate);
  const source = offlineCtx.createBufferSource();
  source.buffer = audioBuffer;
  source.connect(offlineCtx.destination);
  source.start();
  const monoBuffer = await offlineCtx.startRendering();
  return audioBufferToWav(monoBuffer);
}

import React, { useState, useRef, useEffect, useCallback } from 'react';
import { createRoot } from 'react-dom/client';
import WaveSurfer from 'wavesurfer.js';
import RegionsPlugin from 'wavesurfer.js/dist/plugins/regions.esm.js';
import { 
  Play, 
  Pause, 
  Upload, 
  Scissors, 
  RotateCcw, 
  Volume2, 
  Maximize,
  FileAudio,
  Merge,
  Columns,
  Loader2,
  Download,
  X,
  Activity,
  Wind,
  Fingerprint,
  Sparkles,
  TrendingUp,
  TrendingDown,
  SkipBack,
  History
} from 'lucide-react';

import {
  audioBufferToWav,
  applyFade,
  analyzeNoiseProfile,
  applySpectralSubtraction,
  applyNormalization,
  applyNoiseGate,
  applyCut,
  mixToMono
} from './audioUtils';

// --- Types ---

interface AudioState {
  file: File | null;
  originalUrl: string | null;
  currentUrl: string | null;
  monoUrl: string | null;
  duration: number;
  currentTime: number;
  isPlaying: boolean;
  isReady: boolean;
  isMono: boolean;
  isProcessing: boolean;
  processingMsg: string;
  noiseProfile: Float32Array | null;
}

// --- App Component ---

const App: React.FC = () => {
  const [audio, setAudio] = useState<AudioState>({
    file: null,
    originalUrl: null,
    currentUrl: null,
    monoUrl: null,
    duration: 0,
    currentTime: 0,
    isPlaying: false,
    isReady: false,
    isMono: false,
    isProcessing: false,
    processingMsg: '',
    noiseProfile: null,
  });

  const [zoom, setZoom] = useState(0);
  const [isDragging, setIsDragging] = useState(false);
  const [activeRegion, setActiveRegion] = useState<any>(null);

  const containerRef = useRef<HTMLDivElement>(null);
  const wavesurferRef = useRef<WaveSurfer | null>(null);
  const regionsRef = useRef<any>(null);

  // Initialize WaveSurfer
  useEffect(() => {
    if (!containerRef.current || !audio.currentUrl) return;

    const currentTime = wavesurferRef.current?.getCurrentTime() || 0;
    const wasPlaying = wavesurferRef.current?.isPlaying() || false;

    if (wavesurferRef.current) {
      wavesurferRef.current.destroy();
    }

    const ws = WaveSurfer.create({
      container: containerRef.current,
      waveColor: '#6366f1',
      progressColor: '#a5b4fc',
      cursorColor: '#f8fafc',
      barWidth: 2,
      barGap: 1,
      height: 256,
      normalize: true,
      splitChannels: (!audio.isMono) as any,
      url: audio.currentUrl,
      minPxPerSec: 50,
    });

    const regions = ws.registerPlugin(RegionsPlugin.create());
    regionsRef.current = regions;

    ws.on('ready', () => {
      setAudio(prev => ({ ...prev, duration: ws.getDuration(), isReady: true, isProcessing: false, processingMsg: '' }));
      ws.setTime(currentTime > ws.getDuration() ? 0 : currentTime);
      if (wasPlaying) ws.play();
    });

    ws.on('play', () => setAudio(prev => ({ ...prev, isPlaying: true })));
    ws.on('pause', () => setAudio(prev => ({ ...prev, isPlaying: false })));
    ws.on('timeupdate', (time) => setAudio(prev => ({ ...prev, currentTime: time })));

    regions.enableDragSelection({
      color: 'rgba(99, 102, 241, 0.2)',
    });

    regions.on('region-created', (region) => {
      regions.getRegions().forEach(r => {
        if (r !== region) r.remove();
      });
      setActiveRegion(region);
    });

    regions.on('region-updated', (region) => {
      setActiveRegion(region);
    });

    wavesurferRef.current = ws;

    return () => {
      ws.destroy();
    };
  }, [audio.currentUrl, audio.isMono]);

  const handleFileUpload = (file: File) => {
    if (file && file.type.startsWith('audio/')) {
      if (audio.originalUrl) URL.revokeObjectURL(audio.originalUrl);
      if (audio.monoUrl) URL.revokeObjectURL(audio.monoUrl);

      const url = URL.createObjectURL(file);
      setAudio({
        file,
        originalUrl: url,
        currentUrl: url,
        monoUrl: null,
        duration: 0,
        currentTime: 0,
        isPlaying: false,
        isReady: false,
        isMono: false,
        isProcessing: false,
        processingMsg: '',
        noiseProfile: null,
      });
      setActiveRegion(null);
    }
  };

  const handleRevert = () => {
    if (!audio.originalUrl || !confirm("Revert all edits to the original file?")) return;

    setAudio(prev => ({
      ...prev,
      currentUrl: prev.originalUrl,
      isMono: false,
      monoUrl: null,
      noiseProfile: null,
      isProcessing: false,
      processingMsg: ''
    }));
    setActiveRegion(null);
    regionsRef.current?.clearRegions();
  };

  const performProcessing = async (msg: string, processor: (buffer: AudioBuffer, ctx: AudioContext) => AudioBuffer | null | Promise<AudioBuffer | null>) => {
    if (!audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: msg }));

    try {
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const sourceBuffer = await audioCtx.decodeAudioData(arrayBuffer);

      const newBuffer = await processor(sourceBuffer, audioCtx);
      if (!newBuffer) {
        setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
        return;
      }

      const newBlob = audioBufferToWav(newBuffer);
      const newUrl = URL.createObjectURL(newBlob);

      setAudio(prev => ({
        ...prev,
        currentUrl: newUrl,
        isProcessing: false,
        processingMsg: ''
      }));
      setActiveRegion(null);
    } catch (error) {
      console.error("Processing failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleFadeAction = (type: 'in' | 'out') => {
    if (!activeRegion) return;
    performProcessing(`Applying Fade ${type === 'in' ? 'In' : 'Out'}...`, (buffer) => 
      applyFade(buffer, activeRegion.start, activeRegion.end, type)
    );
  };

  const handleAnalyzeNoiseAction = async () => {
    if (!activeRegion || !audio.currentUrl) return;
    setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Analyzing noise fingerprint...' }));

    try {
      const response = await fetch(audio.currentUrl);
      const arrayBuffer = await response.arrayBuffer();
      const audioCtx = new (window.AudioContext || (window as any).webkitAudioContext)();
      const buffer = await audioCtx.decodeAudioData(arrayBuffer);

      const profile = analyzeNoiseProfile(buffer, activeRegion.start, activeRegion.end);

      setAudio(prev => ({
        ...prev,
        noiseProfile: profile,
        isProcessing: false,
        processingMsg: ''
      }));
      alert("Noise fingerprint captured. You can now use 'Clean Atmosphere'.");
    } catch (error) {
      console.error("Analysis failed", error);
      setAudio(prev => ({ ...prev, isProcessing: false, processingMsg: '' }));
    }
  };

  const handleCleanAtmosphereAction = () => {
    if (!audio.noiseProfile) return;
    performProcessing('Cleaning atmospheric noise...', (buffer) => 
      applySpectralSubtraction(buffer, audio.noiseProfile!)
    );
  };

  const handleNormalizeAction = () => {
    performProcessing('Normalizing peaks...', applyNormalization);
  };

  const handleDenoiseAction = () => {
    performProcessing('Removing silence noise...', (buffer) => applyNoiseGate(buffer));
  };

  const handleCutAction = () => {
    if (!activeRegion) return;
    performProcessing('Cutting selection...', (buffer, ctx) => 
      applyCut(buffer, activeRegion.start, activeRegion.end, ctx)
    );
  };

  const handleToggleMono = async () => {
    if (!audio.originalUrl) return;
    if (!audio.isMono) {
      setAudio(prev => ({ ...prev, isProcessing: true, processingMsg: 'Mixing to Mono...' }));
      try {
        const monoBlob = await mixToMono(audio.currentUrl || audio.originalUrl!);
        const monoUrl = URL.createObjectURL(monoBlob);
        setAudio(prev => ({ ...prev, isMono: true, currentUrl: monoUrl, monoUrl: monoUrl, isProcessing: false }));
      } catch (e) { setAudio(prev => ({ ...prev, isProcessing: false })); }
    } else {
      setAudio(prev => ({ ...prev, isMono: false, currentUrl: prev.originalUrl }));
    }
  };

  const handleDownloadAction = () => {
    if (!audio.currentUrl) return;
    const link = document.createElement('a');
    link.href = audio.currentUrl;
    const originalName = audio.file?.name || 'audio';
    const nameWithoutExt = originalName.substring(0, originalName.lastIndexOf('.')) || originalName;
    link.download = `${nameWithoutExt}-edited.wav`;
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  const onDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault();
    setIsDragging(false);
    const file = e.dataTransfer.files[0];
    handleFileUpload(file);
  }, []);

  const togglePlay = () => wavesurferRef.current?.playPause();
  const playRegion = () => activeRegion?.play();
  const seekToStart = () => wavesurferRef.current?.setTime(0);
  const clearRegion = () => {
    regionsRef.current?.clearRegions();
    setActiveRegion(null);
  };

  const handleZoom = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = parseInt(e.target.value);
    setZoom(value);
    wavesurferRef.current?.zoom(value);
  };

  const formatTime = (time: number) => {
    const minutes = Math.floor(time / 60);
    const seconds = Math.floor(time % 60);
    return `${minutes}:${seconds.toString().padStart(2, '0')}`;
  };

  return (
    <div 
      className={`min-h-screen flex flex-col p-6 transition-colors duration-300 ${isDragging ? 'bg-indigo-950/20' : 'bg-slate-900'}`}
      onDrop={onDrop}
      onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
      onDragLeave={(e) => { e.preventDefault(); setIsDragging(false); }}
    >
      <header className="flex justify-between items-center mb-8">
        <div className="flex items-center gap-3">
          <div className="bg-indigo-600 p-2 rounded-lg shadow-lg shadow-indigo-600/20">
            <Volume2 className="w-6 h-6 text-white" />
          </div>
          <h1 className="text-2xl font-bold tracking-tight text-white">AudioWave <span className="text-indigo-400">Editor</span></h1>
        </div>

        <div className="flex items-center gap-3">
          {audio.currentUrl && (
            <>
              <button 
                onClick={handleRevert}
                className="flex items-center gap-2 bg-slate-800 hover:bg-slate-700 text-rose-400 px-4 py-2 rounded-full transition-all border border-slate-700"
                title="Reset to original file"
              >
                <RotateCcw className="w-4 h-4" />
                <span className="text-sm font-medium">Reset All</span>
              </button>
              <button 
                onClick={handleDownloadAction}
                className="flex items-center gap-2 bg-emerald-600 hover:bg-emerald-500 text-white px-4 py-2 rounded-full transition-all shadow-lg shadow-emerald-600/20 border border-emerald-500/50"
              >
                <Download className="w-4 h-4" />
                <span className="text-sm font-medium">Save As</span>
              </button>
            </>
          )}
          <label className="flex items-center gap-2 bg-indigo-600 hover:bg-indigo-500 text-white px-4 py-2 rounded-full cursor-pointer transition-all border border-indigo-500 shadow-lg shadow-indigo-600/20">
            <Upload className="w-4 h-4" />
            <span className="text-sm font-medium">Upload File</span>
            <input type="file" className="hidden" accept="audio/*" onChange={(e) => e.target.files && handleFileUpload(e.target.files[0])} />
          </label>
        </div>
      </header>

      <main className="flex-1 flex flex-col items-center justify-center">
        {!audio.currentUrl ? (
          <div className="text-center p-12 border-2 border-dashed border-slate-700 rounded-3xl max-w-lg w-full bg-slate-800/50 backdrop-blur-sm">
            <FileAudio className="w-16 h-16 text-slate-600 mx-auto mb-4" />
            <h2 className="text-xl font-semibold text-slate-300 mb-2">No audio loaded</h2>
            <p className="text-slate-500 mb-6 text-sm">Drag and drop audio here to begin multi-channel editing and processing.</p>
          </div>
        ) : (
          <div className="w-full max-w-6xl space-y-6">
            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-6 shadow-2xl relative overflow-hidden">
              {audio.isProcessing && (
                <div className="absolute inset-0 z-50 bg-slate-900/80 backdrop-blur-md flex flex-col items-center justify-center">
                  <Loader2 className="w-10 h-10 text-indigo-500 animate-spin mb-4" />
                  <p className="text-white font-medium">{audio.processingMsg}</p>
                </div>
              )}

              <div className="flex justify-between items-center mb-6">
                <div className="flex items-center gap-3">
                  <div className="bg-indigo-500/20 p-1.5 rounded-md border border-indigo-500/30">
                    <History className="w-4 h-4 text-indigo-400" />
                  </div>
                  <div>
                    <h3 className="text-indigo-400 font-medium text-[10px] uppercase tracking-widest">Active Project</h3>
                    <p className="text-white font-semibold truncate max-w-md">{audio.file?.name}</p>
                  </div>
                </div>
                <div className="text-right">
                  <p className="text-slate-400 text-sm font-mono">{formatTime(audio.currentTime)} / {formatTime(audio.duration)}</p>
                </div>
              </div>

              <div className="relative">
                {!audio.isMono && (
                  <>
                    <div className="absolute top-2 left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL L
                    </div>
                    <div className="absolute top-[134px] left-2 z-10 bg-indigo-500/10 text-indigo-300 backdrop-blur-md border border-indigo-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                      CHANNEL R
                    </div>
                  </>
                )}
                {audio.isMono && (
                  <div className="absolute top-2 left-2 z-10 bg-emerald-500/20 text-emerald-400 backdrop-blur-md border border-emerald-500/30 rounded px-2 py-1 text-[10px] font-black uppercase tracking-widest pointer-events-none shadow-sm">
                    MONO MASTER MIX
                  </div>
                )}
                <div ref={containerRef} className="waveform-container rounded-lg bg-slate-900/50 p-2 border border-slate-700/50" />
              </div>
            </div>

            <div className="bg-slate-800 border border-slate-700 rounded-2xl p-4 flex flex-wrap items-center justify-between gap-6 shadow-xl">
              <div className="flex items-center gap-3">
                <button 
                  onClick={seekToStart} 
                  title="Back to Beginning"
                  className="w-10 h-10 flex items-center justify-center rounded-full bg-slate-700 hover:bg-slate-600 text-slate-200 border border-slate-600 transition-all"
                >
                  <SkipBack className="w-5 h-5" />
                </button>
                <button 
                  onClick={togglePlay} 
                  disabled={!audio.isReady || audio.isProcessing}
                  className="w-12 h-12 flex items-center justify-center rounded-full bg-indigo-600 hover:bg-indigo-500 text-white transition-all shadow-lg shadow-indigo-600/20 disabled:opacity-50"
                >
                  {audio.isPlaying ? <Pause /> : <Play className="ml-1" />}
                </button>
                <div className="h-8 w-px bg-slate-700 mx-2" />
                <button 
                  onClick={handleToggleMono}
                  disabled={audio.isProcessing}
                  className={`flex items-center gap-2 px-4 py-2 rounded-lg transition-all text-sm font-semibold border ${
                    audio.isMono 
                    ? 'bg-emerald-600 text-white border-emerald-400 shadow-lg shadow-emerald-600/20' 
                    : 'bg-slate-700 text-slate-300 border-slate-600 hover:bg-slate-600'
                  }`}
                >
                  {audio.isProcessing && audio.processingMsg.includes('Mono') ? (
                    <Loader2 className="w-4 h-4 animate-spin" />
                  ) : audio.isMono ? (
                    <Columns className="w-4 h-4" />
                  ) : (
                    <Merge className="w-4 h-4" />
                  )}
                  {audio.isMono ? 'Stereo' : 'Mix Mono'}
                </button>
              </div>

              <div className="flex items-center gap-4 flex-1 max-w-[200px]">
                <Maximize className="w-4 h-4 text-slate-500" />
                <input type="range" min="0" max="500" value={zoom} onChange={handleZoom} className="flex-1 accent-indigo-500 h-1.5 bg-slate-700 rounded-lg appearance-none cursor-pointer" />
              </div>

              <div className="flex items-center gap-3 border-l border-slate-700 pl-6">
                {activeRegion ? (
                  <>
                    <button 
                      onClick={handleAnalyzeNoiseAction}
