                      title="Fade In Selection"
                    >
                      <TrendingUp className="w-4 h-4" /> Fade In
                    </button>
                    <button 
                      onClick={() => handleFadeAction('out')}
                      className="flex items-center gap-2 px-3 py-2 bg-slate-700 text-slate-300 hover:bg-indigo-600 hover:text-white rounded-lg transition-all text-sm font-semibold border border-slate-600"
                      title="Fade Out Selection"
                    >
                      <TrendingDown className="w-4 h-4" /> Fade Out
                    </button>
                    <div className="h-6 w-px bg-slate-700 mx-1" />
